INSERT INTO level VALUES ('android', 0, 'Ontología', 'El mapa de Android', 'La visión aérea: la plataforma y su ciclo de vida, Jetpack Compose, las librerías de Jetpack, las capacidades del sistema y el camino a Google Play.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 1, 'El ecosistema', 'AOSP, versiones y fragmentación', 'Qué es Android realmente: AOSP, los fabricantes, los niveles de API, la fragmentación y cómo se elige el minSdk en 2026.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 2, 'Android Studio', 'SDK, emulador y adb', 'El entorno: Android Studio y sus ventanas clave, el SDK manager, emuladores y dispositivos, y `adb` como navaja suiza.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 3, 'Gradle para Android', 'KTS, catálogos y variantes', 'El sistema de build: Kotlin DSL, version catalogs, build types y product flavors, y por qué la compilación tarda lo que tarda.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 4, 'Anatomía de una app', 'manifiesto, recursos y AAB', 'Las piezas de una app: el manifiesto, el sistema de recursos y calificadores, R8, y la diferencia entre APK y Android App Bundle.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 5, 'Ciclo de vida', 'Activity, proceso y estado', 'El contrato con el sistema: el ciclo de vida de una Activity, cambios de configuración, la muerte del proceso y restaurar el estado.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 6, 'Compose: fundamentos', 'composables y recomposición', 'El modelo declarativo: funciones componibles, el árbol de composición, las tres fases (composición, layout, dibujo) y los modificadores.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 7, 'Compose: layout', 'el modelo de medida', 'Cómo mide Compose: la pasada única, constraints, `Layout` propio, intrínsecos, y por qué es más eficiente que Auto Layout.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 8, 'Compose: listas', 'Lazy y rendimiento', 'Listas eficientes: `LazyColumn` y `LazyRow`, claves estables, `contentType`, scroll anidado, y el coste de cada elemento.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 9, 'Material 3', 'theming y color dinámico', 'El sistema de diseño: Material 3 y su expressive, color dinámico desde el fondo de pantalla, tipografía, formas y modo oscuro.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 10, 'Compose: animaciones', 'transiciones y gestos', 'Animar en Compose: `animate*AsState`, `AnimatedVisibility`, transiciones compartidas, y gestos con `pointerInput`.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 11, 'Compose: gráficos', 'Canvas y dibujo', 'Dibujo personalizado: `Canvas`, paths, `drawBehind`, brushes y gradientes, y efectos con AGSL en Android 13+.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 12, 'Accesibilidad', 'semántica y TalkBack', 'Apps para todos: el árbol de semántica, `contentDescription`, TalkBack, tamaño de fuente y objetivos táctiles.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 13, 'UI adaptativa', 'plegables, tablets y XR', 'El gran tema de 2026: window size classes, `NavigationSuiteScaffold`, paneles adaptativos, plegables y ventanas redimensionables.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 14, 'Navegación', 'rutas con tipos seguros', 'Navegar en Compose: rutas type-safe con serialización, el back stack, argumentos, y el nuevo modelo de Navigation 3.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 15, 'Arquitectura recomendada', 'capas y flujo unidireccional', 'La guía oficial: capa de UI, de dominio y de datos; flujo unidireccional, offline-first, y su encaje con MVI.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 16, 'Room', 'persistencia relacional', 'Room a fondo: entidades y DAOs, consultas que devuelven `Flow`, relaciones, transacciones y migraciones sin perder datos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 17, 'DataStore', 'preferencias y proto', 'El sustituto de SharedPreferences: Preferences DataStore y Proto DataStore, su naturaleza asíncrona y la migración desde lo viejo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 18, 'Redes', 'Retrofit, Ktor y OkHttp', 'Hablar con el servidor: Retrofit y Ktor Client, interceptores de OkHttp, serialización con kotlinx, y cache HTTP.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 19, 'Paging 3', 'listas infinitas', 'Cargar por páginas: `PagingSource`, `RemoteMediator` para offline-first, estados de carga, y su integración con Compose.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 20, 'WorkManager', 'trabajo diferido', 'Trabajo que debe ocurrir sí o sí: constraints, políticas de reintento, cadenas de trabajos, y trabajo periódico y expedito.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 21, 'Servicios y segundo plano', 'los límites del sistema', 'Foreground services y sus tipos obligatorios, Doze y App Standby, los límites de inicio en segundo plano, y elegir la herramienta correcta.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 22, 'Permisos y privacidad', 'el contrato con el usuario', 'Permisos en tiempo de ejecución, scoped storage, Photo Picker, el manifiesto de datos de Play, y el Privacy Sandbox.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 23, 'Notificaciones', 'canales y push', 'Notificaciones modernas: canales, importancia, el permiso de Android 13+, estilos enriquecidos, y push con Firebase Cloud Messaging.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 24, 'Intents y deep links', 'la app en el sistema', 'El sistema de intents: explícitos e implícitos, filtros, deep links y App Links verificados, y abrir tu app desde cualquier sitio.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 25, 'Interoperar', 'compartir entre apps', 'Android como sistema abierto: el share sheet, Storage Access Framework, content providers, y recibir contenido de otras apps.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 26, 'Cámara y multimedia', 'CameraX y Media3', 'Capturar y reproducir: CameraX (preview, captura, análisis), Media3 y ExoPlayer, y la sesión de medios del sistema.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 27, 'Ubicación y sensores', 'el mundo físico', 'Sensores y posición: el proveedor de ubicación fusionada, precisión aproximada frente a exacta, geofences, y el acelerómetro.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 28, 'Widgets con Glance', 'fuera de la app', 'Widgets de pantalla de inicio escritos en Compose: Glance, su modelo de actualización, y las diferencias con la UI normal.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 29, 'Más allá del móvil', 'Wear, TV, Auto y XR', 'El ecosistema completo: Wear OS con Compose, Android TV, Android Auto, y Android XR; qué se comparte y qué cambia.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 30, 'Testing', 'unidad, UI y dispositivo', 'La pirámide en Android: tests unitarios en la JVM, Robolectric, tests instrumentados, y `composeTestRule` para la interfaz.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 31, 'Rendimiento', 'arranque, R8 y baseline', 'Que la app vuele: tiempo de arranque en frío, baseline profiles, R8 y la minificación, y el presupuesto por frame.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 32, 'Profiling', 'medir con Perfetto', 'Diagnosticar de verdad: los profilers de Android Studio, trazas de Perfetto, Macrobenchmark, y encontrar los jank frames.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 33, 'Seguridad', 'Keystore y biometría', 'Proteger la app y al usuario: Android Keystore, cifrado de datos, autenticación biométrica, Play Integrity y ofuscación.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 34, 'Google Play', 'publicar y actualizar', 'La tienda: firma de apps gestionada por Play, App Bundle y entregas dinámicas, canales de prueba, lanzamiento gradual y políticas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 35, 'CI/CD', 'automatizar el ciclo', 'Automatizar: GitHub Actions con Gradle, cachear dependencias, firmar en CI, y publicar en Play con la API de Play Developer.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 36, 'Multiplataforma', 'KMP y Compose Multiplatform', 'Compartir más allá de Android: Kotlin Multiplatform, Compose Multiplatform en iOS y escritorio, y qué conviene compartir y qué no.', NULL, NULL, NULL);
INSERT INTO level VALUES ('android', 37, 'Síntesis', 'construir y sostener', 'La síntesis: arquitectar una app Android completa, sostenerla entre versiones del sistema, y hacia dónde va la plataforma.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 0, 'Ontología', 'El mapa de la animación web', 'Las cuatro familias (CSS, WAAPI, scroll, librerías), qué resuelve cada una, y el mapa completo del territorio.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 1, 'Principios del movimiento', 'De la animación clásica a la UI', 'Anticipación, follow-through, easing, peso. Qué se traduce a interfaces y qué no, y por qué el movimiento comunica.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 2, 'El pipeline del navegador', 'Style, layout, paint, composite', 'Las etapas del frame, qué dispara cada una, y por qué animar width cuesta cien veces más que animar transform.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 3, 'El hilo del compositor', 'Qué se anima fuera del hilo principal', 'transform, opacity, filter y las animaciones que sobreviven a un hilo principal bloqueado. Cómo verificarlo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 4, 'Transitions', 'La animación de estado', 'Las cuatro propiedades, qué es interpolable, la lista transition-property, y los errores clásicos de timing.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 5, 'Easing', 'cubic-bezier, steps y linear()', 'Leer una curva de Bézier, construir las tuyas, steps para sprites, y linear para aproximar muelles en CSS puro.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 6, 'Animar la entrada', '@starting-style y transition-behavior', 'Animar un elemento que acaba de aparecer, allow-discrete para display y overlay, y el patrón de entrada y salida completo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 7, 'Animar a auto', 'interpolate-size y calc-size', 'El problema de height auto resuelto por fin, interpolate-size con allow-keywords, y las alternativas sin soporte.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 8, 'Keyframes', '@keyframes a fondo', 'Porcentajes múltiples, easing por keyframe, la resolución de propiedades ausentes, y keyframes con variables.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 9, 'Controlar animaciones CSS', 'Las ocho propiedades', 'duration, delay negativo, iteration, direction, fill-mode y play-state como sistema coherente.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 10, 'WAAPI I', 'El método animate', 'La misma potencia desde JS: keyframes como objetos, las dos sintaxis, y por qué devuelve una promesa útil.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 11, 'WAAPI II', 'El objeto Animation', 'play, pause, reverse, currentTime, playbackRate, finished y cancel. Control que CSS no puede dar.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 12, 'WAAPI III', 'Composición y efectos', 'composite con add y accumulate, KeyframeEffect reutilizable, getAnimations y pausar todo el documento.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 13, 'El bucle de render', 'requestAnimationFrame y el tiempo', 'Cuándo sigues necesitando rAF, el delta time correcto, el problema del framerate variable, y cancelar bien.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 14, 'Scroll-driven I', 'El modelo de timelines', 'Separar la animación del tiempo: qué es una timeline, y por qué esto elimina el 90% del JS de scroll.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 15, 'Scroll-driven II', 'scroll() y animation-timeline', 'La progress timeline del scroll, elegir el scroller y el eje, y la barra de progreso en tres líneas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 16, 'Scroll-driven III', 'view() y los rangos', 'La view timeline de un elemento al cruzar el viewport, animation-range, los nombres de rango y view-timeline-inset.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 17, 'Scroll-driven IV', 'El fallback y Firefox', 'Firefox no lo ha implementado en 2026: detectar con @supports, el polyfill, y la estrategia de mejora progresiva.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 18, 'View Transitions I', 'Mismo documento', 'El método startViewTransition, el árbol de pseudo-elementos, y qué hace el navegador con las capturas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 19, 'View Transitions II', 'Nombres, grupos y personalización', 'view-transition-name, los elementos que hacen morphing, los tipos de transición y animar cada parte.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 20, 'View Transitions III', 'Entre documentos', 'La regla view-transition en MPA, los eventos pageswap y pagereveal, y la navegación con transición sin SPA.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 21, 'Animar SVG', 'CSS, SMIL y el DOM', 'Las tres vías, animar el trazo con stroke-dasharray, transformaciones en SVG y sus sistemas de coordenadas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 22, 'Rutas y recorridos', 'offset-path y motion path', 'Mover elementos por un trazado, offset-distance, offset-rotate y las formas de ruta modernas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 23, 'Física del movimiento', 'Muelles, inercia y amortiguación', 'La ecuación del muelle amortiguado, rigidez y masa como parámetros de diseño, y por qué se sienten reales.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 24, 'GSAP I', 'Por qué existe y por qué es gratis', 'Qué resuelve que las APIs nativas no, la licencia desde abril de 2025 con Webflow, y el mapa de plugins.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 25, 'GSAP II', 'Los tweens: to, from, fromTo, set', 'El modelo de tween, el objeto vars, el targeting, y las propiedades especiales de GSAP.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 26, 'GSAP III', 'Timelines', 'Secuenciar sin sumar delays: la posición relativa, las etiquetas, timelines anidadas y el control global.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 27, 'GSAP IV', 'Eases y el visualizador', 'El sistema completo de eases, CustomEase, los eases de rebote y elásticos, y cuándo cada uno.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 28, 'GSAP V', 'Stagger y utilidades', 'El stagger avanzado con grid y from, y las utilidades: mapRange, snap, random, wrap, interpolate.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 29, 'GSAP VI', 'ScrollTrigger: el modelo', 'trigger, start y end, los marcadores, toggleActions, y el modelo mental que hace que todo encaje.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 30, 'GSAP VII', 'ScrollTrigger: pin y scrub', 'Fijar secciones, el scrub con suavizado, snap, las secciones horizontales y el refresh en resize.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 31, 'GSAP VIII', 'SplitText', 'Dividir en caracteres, palabras y líneas, el reflow responsive, el masking de líneas y revertir bien.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 32, 'GSAP IX', 'Flip', 'El patrón FLIP resuelto: getState, from, animar entre layouts imposibles y el reordenado de listas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 33, 'GSAP X', 'Plugins de SVG', 'MorphSVG entre formas arbitrarias, DrawSVG para dibujar trazos, y MotionPath con alineación.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 34, 'GSAP XI', 'Interacción', 'Observer para gestos unificados, Draggable con inercia, ScrollSmoother y ScrollTo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 35, 'GSAP XII', 'Integración y limpieza', 'El contexto y matchMedia, la limpieza en componentes, useGSAP, y el patrón con Solid y con Astro.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 36, 'Motion y las alternativas', 'El resto del ecosistema', 'Motion (antes Framer Motion), Anime.js, Popmotion y auto-animate: qué elige cada quién y por qué.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 37, 'Lottie y After Effects', 'La animación del diseñador', 'El formato, el pipeline desde After Effects, dotLottie, el coste real en runtime y las alternativas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 38, 'Accesibilidad', 'prefers-reduced-motion en serio', 'Qué significa reducir el movimiento (no eliminarlo), el trastorno vestibular, y el patrón de dos versiones.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 39, 'Rendimiento', 'Medir el jank de verdad', 'El panel de rendimiento, las capas del compositor, los long tasks, y diagnosticar por qué cae a 30fps.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 40, 'Depurar animaciones', 'El panel de animaciones', 'Inspeccionar, ralentizar y editar animaciones en vivo, y el flujo de trabajo para ajustar timing.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 41, 'Coreografía', 'Sistemas de movimiento', 'Tokens de duración y easing, la jerarquía del movimiento, y documentar el movimiento en un design system.', NULL, NULL, NULL);
INSERT INTO level VALUES ('animacion', 42, 'Síntesis', 'Síntesis de la animación web', 'El árbol de decisión completo, el catálogo de patrones resueltos, y hacia dónde va la animación en la web.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 0, 'Ontología', 'El mapa de Astro', 'La visión aérea de Astro 7: islands, content, SSR/SSG, el compilador en Rust, y el mapa del camino.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 1, 'Por qué Astro', 'islands y content-first', 'La filosofía: HTML por defecto, cero JS salvo donde hace falta (islands), y el enfoque content-first.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 2, 'Setup y proyecto', 'Astro 7, Vite 8, Rolldown', 'Crear un proyecto, la estructura, y el stack de 2026: compilador en Rust, Vite 8 con Rolldown.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 3, 'El componente .astro', 'frontmatter y template', 'La anatomía de un componente Astro: el script del frontmatter y el template HTML.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 4, 'Templating', 'expresiones y directivas', 'Expresiones JSX-like, map, condicionales, Fragment, y las directivas de template.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 5, 'Props y slots', 'componer componentes', 'Pasar datos con props (tipados), slots nombrados, y el patrón de composición.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 6, 'Estilos', 'scoped, global, CSS', 'Estilos con scope automático, globales, variables CSS, y la integración con Tailwind/CSS.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 7, 'Layouts', 'plantillas compartidas', 'Layouts como componentes envolventes, slots, y el patrón head/body.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 8, 'Routing por archivos', 'src/pages', 'El enrutado basado en archivos, index, y la estructura de páginas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 9, 'Rutas dinámicas', 'params y getStaticPaths', 'Rutas dinámicas ([slug], [...rest]), getStaticPaths, y params.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 10, 'Routing avanzado', 'redirects, paginación, rewrites', 'Redirecciones en config y Astro.redirect, paginación con paginate(), la prop page, rewrites y prioridad de rutas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 11, 'Content Collections', 'glob loader y schema', 'Colecciones de contenido con el content layer: content.config.ts, glob loader, Zod schema, getCollection y render.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 12, 'Content Layer API', 'loaders personalizados', 'La Content Layer API: loaders integrados y propios, el store, parseData, y caching incremental.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 13, 'Markdown a fondo', 'remark, rehype, headings', 'Markdown como página, render() y getHeadings, plugins remark y rehype, y la config global de markdown.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 14, 'MDX a fondo', 'componentes y expresiones', 'Qué añade MDX, usar componentes dentro del contenido, expresiones y exportaciones, layouts, y el prop components.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 15, 'Resaltado de código', 'Shiki y transformers', 'Resaltado nativo con Shiki, temas dual claro/oscuro, el componente Code, transformers, y cliente vs servidor.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 16, 'RSS, sitemap y datos', 'feeds y datos derivados', 'Feed RSS con @astrojs/rss, sitemap, endpoints de datos, import.meta.glob, y robots/canonical/Open Graph.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 17, 'Arquitectura de islas', 'client:load, visible, only', 'La arquitectura de islas: client:load/idle/visible/media/only, compartir estado y el coste de la hidratación.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 18, 'Integraciones de framework', 'React, Solid, Vue, Svelte', 'astro add y los renderers, pasar props y slots, anidar frameworks distintos, y estado compartido con nanostores.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 19, 'Server Islands', 'server:defer y fallback', 'Server islands: server:defer, el contenido fallback, cómo funcionan por dentro, casos de uso y límites.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 20, 'SSR, SSG e híbrido', 'output y prerender', 'Los modos de render de Astro 7, prerender por página, el objeto Astro en SSR, y estrategias de render.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 21, 'Adapters', 'Node, Cloudflare, Vercel', 'Qué es un adapter, @astrojs/node, adapters de edge y serverless, configurarlos y elegir plataforma.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 22, 'Endpoints y API', 'rutas de servidor', 'Endpoints estáticos y SSR, verbos y APIContext, params dinámicos, streaming y CORS, y patrones reales.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 23, 'Middleware', 'onRequest y locals', 'El middleware: onRequest, context.locals tipado, modificar la respuesta, sequence, y casos reales.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 24, 'Actions', 'funciones de servidor tipadas', 'Astro Actions: defineAction, input con Zod, llamarlas (data/error), formularios progresivos y errores tipados.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 25, 'Sesiones y estado', 'Astro.session y cookies', 'La Sessions API, drivers de almacenamiento, cookies con Astro.cookies, auth con sesión y seguridad.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 26, 'View Transitions', 'ClientRouter y transiciones', 'El ClientRouter, transition:name/animate, transition:persist, los eventos del ciclo y accesibilidad.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 27, 'Imágenes', 'astro:assets', 'El componente Image, Picture y formatos, imágenes remotas y en colecciones, getImage, y rendimiento/CLS.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 28, 'Fuentes (Fonts API)', 'fuentes optimizadas', 'La Fonts API: familias y proveedores, el componente Font y el preload, rendimiento tipográfico y autoalojar.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 29, 'Variables de entorno', 'astro:env', 'import.meta.env, el schema tipado de astro:env, leer client/server y getSecret, secretos y buenas prácticas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 30, 'i18n', 'internacionalización', 'El routing i18n integrado, los helpers de URL por locale, contenido traducido y fallback, y SEO multiidioma.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 31, 'Seguridad', 'CSP, XSS, cabeceras', 'XSS y set:html, Content Security Policy, cabeceras de seguridad, CSRF y checkOrigin, y buenas prácticas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 32, 'SEO', 'metadatos, OG, JSON-LD', 'Metadatos base y canonical, Open Graph y og:image dinámica, datos estructurados JSON-LD, indexación y Web Vitals.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 33, 'Prefetch y navegación', 'estrategias de prefetch', 'La feature prefetch y sus estrategias, prefetchAll, la API programática, presupuesto LCP/INP y medición.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 34, 'Escribir integraciones', 'Integration API', 'La Integration API: AstroIntegration, el hook astro:config:setup, otros hooks del ciclo, módulos virtuales y publicar.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 35, 'El compilador en Rust', 'el pipeline de Astro 7', 'Por qué un compilador propio, el pipeline parse/transform, islas e hidratación en el output, WASM vs binario nativo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 36, 'Vite 8 y Rolldown', 'el motor por debajo', 'El rol de Vite, Rolldown el bundler en Rust, configurar Vite desde astro.config, el grafo de módulos y diagnóstico.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 37, 'Rendimiento', 'Core Web Vitals', 'El presupuesto de JS, Core Web Vitals a fondo, analizar el bundle, optimizar assets/CSS/caché y el SSR.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 38, 'Testing', 'Vitest, Container, Playwright', 'Estrategia de testing, Vitest en Astro, la Container API, testear endpoints y actions, y e2e con Playwright.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 39, 'Deploy', 'a producción', 'Anatomía del build, deploy estático y SSR/edge, CI/CD con GitHub Actions, y operar en producción.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 40, 'Arquitectura a escala', 'proyectos grandes', 'Estructura de un proyecto serio, monorepos con pnpm/Turborepo, contenido a escala, composición y mantenibilidad.', NULL, NULL, NULL);
INSERT INTO level VALUES ('astro', 41, 'Síntesis', 'arquitectura y trade-offs', 'El modelo mental completo, diseñar el render por página, rendimiento extremo, un caso de estudio integral y el futuro.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 0, 'Ontología', 'El mapa del build', 'La visión aérea del camino a producción: módulos, package managers, Vite, el bundler, empaquetado, monorepos, caching y deploy. El mapa mental completo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 1, 'Por qué existe el build', 'módulos y navegadores', 'El problema que resuelven las build tools: módulos, compatibilidad de navegadores, TypeScript/JSX, y una breve historia de webpack a Vite.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 2, 'Módulos JS', 'ESM vs CommonJS', 'El sistema de módulos: ESM (import/export), CommonJS (require), dynamic import, y la interoperabilidad entre ambos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 3, 'Package managers', 'npm, yarn, pnpm', 'Los gestores de paquetes: npm vs yarn vs pnpm, y por qué pnpm gana con su store de contenido enlazado y su ahorro de disco.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 4, 'package.json a fondo', 'campos y scripts', 'La anatomía de package.json: dependencies vs devDependencies, scripts, semver, engines, y los campos que importan.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 5, 'Resolución de módulos', 'exports e imports', 'Cómo Node y los bundlers resuelven un import: el campo exports, conditions, subpath imports, y los mapas de resolución.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 6, 'Lockfiles', 'reproducibilidad', 'Los lockfiles (pnpm-lock.yaml): builds reproducibles, el árbol de dependencias, hoisting, y por qué NO borrarlos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 7, 'pnpm workspaces', 'el monorepo básico', 'Workspaces de pnpm: varios paquetes en un repo, el protocolo workspace, --filter para tareas selectivas, y dependencias internas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 8, 'pnpm catalogs', 'versiones compartidas', 'Catalogs: definir versiones de dependencias una sola vez y referenciarlas; catalogMode strict/prefer/manual; coherencia a escala.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 9, 'El registro npm', 'publicar paquetes', 'El registro: publicar, paquetes scoped, dist-tags, provenance (procedencia firmada), y alternativas como JSR.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 10, 'Vite', 'el dev server moderno', 'Qué es Vite: dev server sobre ESM nativo del navegador, arranque instantáneo, y por qué reemplazó a webpack en dev.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 11, 'HMR', 'hot module replacement', 'Cómo funciona el HMR: el grafo de módulos, aceptar actualizaciones sin recargar, preservar estado, y la API import.meta.hot.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 12, 'Configurar Vite', 'plugins y resolve', 'La config de Vite: plugins, resolve.alias, server, define, css, y cómo estructurar una configuración mantenible.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 13, 'optimizeDeps', 'pre-bundling', 'El pre-bundling de dependencias con esbuild: por qué Vite convierte CJS a ESM y agrupa deps para reducir peticiones en dev.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 14, 'Ecosistema de plugins', 'Rollup-compatible', 'El sistema de plugins de Vite (compatible con Rollup): hooks, transformar código, módulos virtuales, y escribir el tuyo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 15, 'La Environment API', 'multi-entorno y SSR', 'La Environment API de Vite: modelar cliente, SSR y edge como entornos separados; el nuevo modelo que unifica dev y build.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 16, 'Dev vs build', 'las dos mitades', 'Las dos naturalezas de Vite: ESM sin bundle en dev vs un bundle optimizado en build; por qué difieren y sus implicaciones.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 17, 'Qué hace un bundler', 'el grafo de módulos', 'La anatomía de un bundler: entry points, el grafo de módulos, resolución, transformación y la generación del output.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 18, 'Rollup', 'el modelo de plugins', 'Rollup: el bundler que definió el modelo; output formats (esm, cjs, iife), plugins, y por qué Vite lo usó en build.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 19, 'Rolldown', 'el bundler en Rust', 'Rolldown 1.0 (sobre Oxc): el bundler en Rust que reemplaza a esbuild y Rollup en Vite 8; API compatible con Rollup y builds 10-30x más rápidos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 20, 'esbuild, SWC y Oxc', 'el toolchain en Rust/Go', 'Los transformadores rápidos: esbuild (Go, bundler+transform), SWC (Rust, transform), Oxc (Rust, todo el toolchain); qué usa cada capa.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 21, 'Tree shaking', 'eliminar código muerto', 'Tree shaking: análisis estático para quitar lo que no se usa; el papel de ESM, sideEffects en package.json, y sus límites.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 22, 'Code splitting', 'dividir el bundle', 'Code splitting: dividir el código en chunks cargados bajo demanda; dynamic import, chunks compartidos, y la estrategia de división.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 23, 'Lazy loading', 'cargar bajo demanda', 'Lazy loading: diferir código no crítico; por ruta y por componente, prefetch/preload, y el equilibrio con el número de peticiones.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 24, 'Minificación', 'terser, esbuild, oxc', 'Minificar el output: terser vs esbuild vs oxc-minify, mangling, compresión, y los source maps para depurar en producción.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 25, 'Assets', 'CSS, imágenes, fuentes', 'El pipeline de assets: importar CSS/imágenes/fuentes, hashing para cache-busting, inlining de assets pequeños, y CSS code splitting.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 26, 'Empaquetar una librería', 'ESM, CJS, tipos', 'Publicar una librería: qué formatos ofrecer (ESM, CJS, UMD), incluir tipos de TypeScript, y qué NO empaquetar (externals).', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 27, 'exports para librerías', 'dual package', 'El campo exports para librerías: dual package (ESM+CJS), conditions (import/require/types), subpaths, y el peligro del dual package hazard.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 28, 'Herramientas de build', 'Vite lib, tsup, unbuild', 'Construir la librería: Vite en lib mode, tsup (esbuild), unbuild (rollup); generar tipos con dts, y elegir herramienta.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 29, 'Publicar la librería', 'versiones y provenance', 'Publicar: versionado semántico, dist-tags (latest/next), provenance firmada, empaquetar solo lo necesario (files), y npm vs JSR.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 30, 'Changesets', 'versionado en monorepo', 'Changesets: declarar el impacto de cada cambio, versionar múltiples paquetes de forma coordinada, generar changelogs y publicar en CI.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 31, 'Monorepos', 'por qué y cómo', 'Monorepos: un repo con muchos paquetes; ventajas (código compartido, cambios atómicos), retos (build, CI), y el panorama de herramientas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 32, 'Turborepo', 'task graph y caching', 'Turborepo: el grafo de tareas, el pipeline (turbo.json), inputs/outputs, y el caching local que evita re-ejecutar lo que no cambió.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 33, 'Remote caching', 'compartir la caché', 'Remote caching: subir artefactos de build a una caché compartida (Vercel o self-hosted) para que otra máquina o CI reutilice el resultado.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 34, 'Nx', 'el build system completo', 'Nx: grafo de tareas, plugins y generadores, Nx Cloud con Replay, y distributed task execution (DTE) que reparte tareas entre máquinas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 35, 'Elegir herramienta', 'Turborepo vs Nx vs Moon', 'Comparar los build systems: Turborepo (simple, rápido) vs Nx (completo, plugins) vs Moon; criterios para elegir según tu equipo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 36, 'Cómo funciona la caché', 'hashing e invalidación', 'La caché por dentro: hashing de inputs (archivos, deps, env), qué invalida un hit, y la seguridad (envenenamiento de caché, el CVE CREEP).', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 37, 'Module Federation', 'microfrontends', 'Module Federation: compartir código entre apps en runtime; microfrontends, equipos independientes, remotes/host, y sus trade-offs.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 38, 'Optimización de producción', 'bundle budgets', 'Optimizar el output: analizar el bundle (visualizer), presupuestos de tamaño, dividir vendor, y perseguir Core Web Vitals desde el build.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 39, 'CI/CD para frontend', 'pipeline y deploy', 'La tubería a producción: instalar con caché, lint/test/build, la caché remota en CI, previews por PR, y desplegar al edge o a un CDN.', NULL, NULL, NULL);
INSERT INTO level VALUES ('build', 40, 'Síntesis', 'el toolchain unificado', 'La imagen completa: arquitectar el build de un producto a escala, el toolchain unificado en Rust (VoidZero: Vite, Rolldown, Oxc), y hacia dónde va todo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 0, 'Ontología', 'El mapa de C y la programación de sistemas', 'La ontología completa: qué es C, dónde vive, cómo se relaciona todo, y un mapa mental de todo el territorio que vas a conquistar.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 1, 'Por qué C hoy', 'La mentalidad de sistemas', 'Historia, filosofía y el lugar de C23 frente a versiones anteriores. La mentalidad del programador de sistemas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 2, 'Setup y toolchain', 'GCC, Clang y el depurador', 'gcc y clang, compilar con -std=c23, tu primer programa y el entorno de desarrollo moderno.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 3, 'El proceso de compilación', 'Las cuatro fases, vistas', 'Las cuatro fases: preprocesado, compilación, ensamblado y linking. Qué produce exactamente cada una.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 4, 'Practicante', 'Tipos y novedades de C23', 'Tipos fundamentales y lo nuevo: auto, constexpr, nullptr, typeof, _BitInt y enums con tipo fijo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 5, 'Competente', 'Operadores y expresiones', 'Precedencia, promociones enteras, conversiones implícitas y sus trampas clásicas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 6, 'Hábil', 'Control de flujo', 'if, switch, bucles y las mejoras de C23. Flujo idiomático, claro y sin sorpresas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 7, 'Diestro', 'Funciones a fondo', 'Parámetros, retorno, scope, storage classes e inline. Cómo se organiza y se llama el código.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 8, 'Punteros I', 'Punteros I: fundamentos', 'El concepto que define a C: direcciones, dereferencia, aritmética de punteros y nullptr.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 9, 'Adepto', 'Arrays y strings', 'Decaimiento a puntero, arrays de longitud variable y el manejo (peligroso) de cadenas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 10, 'Punteros II', 'Punteros II: avanzado', 'Punteros a función, dobles punteros, const correctness y patrones profesionales.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 11, 'Veterano', 'Structs y unions', 'Layout en memoria, alineación, padding, bitfields y flexible array members.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 12, 'Especialista', 'Enums y typedef', 'Enumeraciones con tipo subyacente fijo (C23) y el arte de typedef para modelar.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 13, 'Ingeniero', 'Memoria dinámica', 'malloc, calloc, realloc y free. El heap, los patrones correctos y los errores clásicos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 14, 'Gestión de memoria', 'Gestión de memoria avanzada', 'Arenas, pools, ownership manual y estrategias de asignación que escalan sin fugas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 15, 'Táctico', 'El preprocesador a fondo', 'Macros, #embed, X-macros y _Generic: la metaprogramación que es posible en C.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 16, 'Modular', 'Modularidad y linkage', 'Unidades de traducción, headers, extern, y linkage interno frente a externo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 17, 'Constructor', 'Build con Meson', 'El sistema de build moderno: targets, dependencias, opciones y sanitizers integrados.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 18, 'Herrero', 'Make y el tooling clásico', 'Makefiles, autotools y cuándo elegir cada herramienta de construcción.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 19, 'Bibliotecario', 'Bibliotecas estáticas y dinámicas', 'Crear y usar .a y .so, y las implicaciones profundas de cada tipo de enlace.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 20, 'Enlazador', 'El linker y ELF', 'Resolución de símbolos, visibilidad, versioning, LTO y el formato ELF por dentro.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 21, 'ABI y convenciones de llamada', 'ABI y calling conventions', 'La interfaz binaria: System V, convenciones de llamada y estabilidad de ABI.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 22, 'Sabio', 'libc: glibc vs musl', 'Qué es una libc, syscalls, POSIX, y las diferencias reales entre glibc y musl.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 23, 'Mago', 'Freestanding y no-libc', '-ffreestanding, -nostdlib, bare metal y escribir tu propio runtime mínimo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 24, 'Guardián', 'Sanitizers', 'ASan, UBSan, MSan y TSan: cazar bugs de memoria y comportamiento en ejecución.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 25, 'Cazador', 'Análisis estático y fuzzing', 'clang-tidy, cppcheck, Valgrind y libFuzzer: encontrar bugs antes de que ocurran.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 26, 'Centinela', 'Seguridad y hardening', 'Mitigaciones del compilador, stack protector, secure coding y superficie de ataque.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 27, 'Sincronizador', 'Concurrencia', 'Hilos C11/C23, atomics, el modelo de memoria y la sincronización correcta.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 28, 'Optimizador', 'Bajo nivel y rendimiento', 'Inline asm, SIMD/intrinsics, jerarquía de caché, perf y optimización guiada por datos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 29, 'Semidiós', 'Undefined Behavior', 'El estándar como fuente de verdad, el UB a fondo y cómo lo explota el optimizador.', NULL, NULL, NULL);
INSERT INTO level VALUES ('c23', 30, 'Proyectos finales', 'Construye lo imposible', 'Tu propia libc mínima, un allocator desde cero y una mirada a los internals del compilador.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 0, 'Ontología', 'El mapa del gráfico 2D en la web', 'Canvas frente a SVG frente a CSS: los tres modelos de gráfico, qué resuelve cada uno, y el mapa del territorio.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 1, 'Raster y vector', 'Los dos modelos de imagen', 'La diferencia profunda entre pintar píxeles y describir formas, y las consecuencias en escalado, memoria y accesibilidad.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 2, 'Canvas: el contexto 2D', 'Empezar a pintar', 'getContext, el sistema de coordenadas, el modo inmediato, y por qué el canvas no recuerda lo que dibujaste.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 3, 'Resolución y DPI', 'El canvas nítido en pantallas retina', 'La diferencia entre tamaño CSS y tamaño de buffer, devicePixelRatio, y el patrón correcto de redimensionado.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 4, 'Formas y rutas', 'El modelo de path', 'beginPath, moveTo, lineTo, las curvas de Bézier y arc, y por qué el orden de las llamadas importa.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 5, 'Trazo y relleno', 'Estilos de línea y pintura', 'lineWidth, cap y join, el patrón de guiones, fillStyle con gradientes y patrones, y la regla de relleno.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 6, 'Transformaciones', 'La matriz del contexto', 'translate, rotate, scale y transform, la pila con save y restore, y pensar en espacios locales.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 7, 'Texto en canvas', 'Medir y componer', 'fillText, measureText y sus métricas completas, la línea base, y componer texto multilínea a mano.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 8, 'Imágenes', 'drawImage y sus tres formas', 'Las tres firmas, el recorte, el sprite sheet, ImageBitmap y la decodificación fuera del hilo principal.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 9, 'Píxeles', 'ImageData y el acceso directo', 'getImageData y putImageData, el array de píxeles, los filtros a mano, y el coste de leer del canvas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 10, 'Composición', 'globalCompositeOperation', 'Los operadores de Porter-Duff, los modos de fusión, el recorte con clip, y los efectos que desbloquean.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 11, 'Path2D y OffscreenCanvas', 'Reutilizar y salir del hilo', 'Path2D como objeto reutilizable, OffscreenCanvas en un worker, y transferControlToOffscreen.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 12, 'Interacción en canvas', 'Hit testing sin DOM', 'isPointInPath, el hit testing por color, mantener un modelo de escena, y la accesibilidad del canvas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 13, 'Animación en canvas', 'El bucle y el estado', 'La estructura update y draw, el delta time, el borrado parcial para estelas, y la interpolación.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 14, 'Rendimiento del canvas', 'Lo que realmente cuesta', 'Los cambios de estado, el canvas de caché, dibujar solo lo sucio, y cuándo el canvas deja de ser la respuesta.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 15, 'SVG: el documento', 'Un lenguaje, no un formato', 'SVG es XML en el DOM: el viewBox, preserveAspectRatio, el sistema de coordenadas y las unidades.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 16, 'Formas SVG', 'El catálogo de elementos', 'rect, circle, ellipse, line, polyline, polygon: sus atributos y cuándo usar cada uno frente a path.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 17, 'El elemento path', 'El mini-lenguaje de la d', 'Los comandos M, L, H, V, C, S, Q, T, A y Z, mayúsculas frente a minúsculas, y leer una d a ojo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 18, 'Estilar SVG', 'Presentación, CSS y herencia', 'Atributos de presentación frente a CSS, qué se puede estilar, las variables CSS en SVG y la especificidad.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 19, 'Reutilizar en SVG', 'defs, use, symbol y sprites', 'El patrón de sprite SVG, use y su shadow DOM, symbol con su propio viewBox, y los límites del estilado.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 20, 'Gradientes y patrones', 'Rellenos complejos', 'linearGradient y radialGradient, las unidades de gradiente, pattern, y las referencias por id.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 21, 'Recorte y máscara', 'clipPath y mask en SVG', 'La diferencia entre recortar y enmascarar, las unidades de contenido, y el uso desde CSS.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 22, 'Filtros SVG', 'El pipeline de primitivas', 'feGaussianBlur, feColorMatrix, feTurbulence, feDisplacementMap y encadenar primitivas para efectos reales.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 23, 'Texto en SVG', 'text, tspan y textPath', 'Posicionar texto, tspan para tramos, texto sobre una ruta, y el problema de las fuentes en SVG exportado.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 24, 'SVG y accesibilidad', 'Gráficos que se pueden leer', 'title y desc, los roles ARIA, cuándo es decorativo, y el patrón para iconos y para gráficas de datos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 25, 'Optimizar SVG', 'SVGO y el flujo desde el diseño', 'Qué produce Figma e Illustrator, qué quitar sin romper, la precisión decimal, y el SVG inline frente al externo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 26, 'SVG generado', 'Construir gráficos por código', 'Crear SVG desde JS con el namespace correcto, generar rutas por datos, y el patrón de componente de gráfico.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 27, 'Visualización de datos I', 'Escalas y ejes', 'El concepto de escala, mapear dominio a rango, los tipos de escala, y construir un eje a mano.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 28, 'Visualización de datos II', 'D3 y el modelo de datos', 'La filosofía de D3, el join de datos, los generadores de forma, y usar D3 solo para la matemática.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 29, 'Visualización de datos III', 'Elegir la representación', 'Qué gráfico para qué pregunta, los errores clásicos de percepción, el color en datos y el eje truncado.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 30, 'Canvas o SVG', 'El árbol de decisión', 'El umbral de elementos, la interacción, la accesibilidad, la impresión, y el enfoque híbrido.', NULL, NULL, NULL);
INSERT INTO level VALUES ('canvas', 31, 'Síntesis', 'Síntesis del gráfico 2D', 'La arquitectura de un sistema de visualización completo, el mapa de decisiones, y el futuro del 2D en la web.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 0, 'Ontología', 'El mapa de Cloudflare', 'La visión aérea de la plataforma developer de Cloudflare: Workers en el edge, el almacenamiento (KV, R2, D1, DO), la IA, y el despliegue. El mapa mental completo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 1, 'Qué es el edge', 'la red global', 'Qué es Cloudflare y el edge: cientos de ubicaciones cerca del usuario; por qué ejecutar código ahí cambia la latencia y la arquitectura.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 2, 'Isolates', 'no son contenedores', 'El modelo de ejecución de Workers: V8 isolates en vez de contenedores o funciones lambda; arranque en 0ms, sin cold starts, y sus implicaciones.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 3, 'El primer Worker', 'el fetch handler', 'Anatomía de un Worker: el `fetch` handler que recibe una `Request` y devuelve una `Response`; el modelo mental de "una función en el edge".', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 4, 'Wrangler', 'el CLI', 'Wrangler: crear un proyecto, `wrangler dev` (local con workerd), `wrangler deploy`, y `wrangler.jsonc` como el manifiesto del Worker.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 5, 'El runtime', 'workerd y Web APIs', 'El runtime de Workers: `workerd` (open source), las Web APIs estándar en vez de Node, las compatibility dates y flags, y el nodejs_compat.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 6, 'Bindings', 'el modelo de acceso', 'Los bindings: cómo un Worker accede a recursos (KV, R2, D1, otro Worker) por el objeto `env`; capacidades declaradas, no credenciales.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 7, 'Routing y dominios', 'workers.dev y custom', 'Enrutar peticiones a un Worker: rutas, dominios personalizados, `workers.dev`, y cómo Cloudflare decide qué Worker atiende cada request.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 8, 'Variables y secretos', 'vars y Secrets Store', 'Configuración: `vars` en el manifiesto, secretos con `wrangler secret`, el Secrets Store, y separar entornos sin filtrar credenciales.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 9, 'Observabilidad', 'logs, tail, analytics', 'Ver qué hace tu Worker: `wrangler tail`, Workers Logs, Analytics Engine para métricas propias, y depurar en producción.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 10, 'Request y Response', 'streaming en el edge', 'Trabajar con `Request`/`Response`: leer body, cabeceras, `fetch` saliente (subrequests), y hacer streaming de respuestas con `ReadableStream`.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 11, 'Static Assets', 'la paridad con Pages', 'Servir sitios estáticos y SSR desde un Worker: la config de `assets`; en 2026 Workers tiene paridad total con Pages (assets, SSR, dominios).', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 12, 'Cron Triggers', 'workers programados', 'Ejecutar un Worker en un horario: el `scheduled` handler y los cron triggers; tareas periódicas sin un servidor que las lance.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 13, 'Service bindings', 'worker a worker', 'Componer Workers: llamar a otro Worker por RPC con service bindings (sin salir a la red); arquitecturas de microservicios en el edge.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 14, 'Frameworks en Workers', 'Hono y full-stack', 'Construir apps reales: Hono como router ligero, y frameworks full-stack (Astro, Remix, SvelteKit) desplegados en Workers.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 15, 'Smart Placement y límites', 'CPU y subrequests', 'El rendimiento del edge: Smart Placement (mover el Worker cerca de los datos), y los límites reales (tiempo de CPU, memoria, subrequests).', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 16, 'Containers y Workflows', 'lo nuevo en compute', 'Más allá de Workers: Containers (ejecutar imágenes junto al edge) y Workflows (procesos durables de varios pasos con reintentos).', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 17, 'KV', 'clave-valor global', 'Workers KV: almacén clave-valor de lectura rápida y global; consistencia eventual, cache en el edge, y sus casos ideales y límites.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 18, 'R2', 'almacenamiento de objetos', 'R2: almacenamiento de objetos compatible con S3 y SIN cargos de egress; servir archivos, backups, y el patrón de subidas presignadas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 19, 'D1', 'SQLite en el edge', 'D1 (GA): una base de datos SQLite serverless; crear la base, el binding, y ejecutar SQL desde el Worker con la API `prepare`/`bind`.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 20, 'D1 avanzado', 'migraciones y réplicas', 'D1 en serio: migraciones versionadas, la Sessions API para consistencia read-your-writes, read replication global, y batch.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 21, 'Durable Objects', 'el modelo', 'Durable Objects: un objeto único y direccionable con estado consistente; el actor con identidad global que resuelve la coordinación en el edge.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 22, 'DO: storage y alarms', 'estado transaccional', 'El estado de un DO: el storage transaccional (KV y SQLite), las alarms para despertarse solo, y la garantía de single-threaded.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 23, 'DO: WebSockets', 'tiempo real e hibernación', 'DO para tiempo real: coordinar WebSockets (chat, colaboración, juegos), y la WebSocket Hibernation que reduce el coste cuando no hay tráfico.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 24, 'Queues', 'mensajería asíncrona', 'Cloudflare Queues: productores y consumidores, entrega garantizada, batching, reintentos y dead-letter; desacoplar trabajo sin cargos de egress.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 25, 'Hyperdrive', 'acelerar tu Postgres', 'Hyperdrive: conectar tu Postgres/MySQL existente desde el edge con pooling y cache de queries; cuándo elegirlo frente a D1.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 26, 'Cache API', 'la cache del edge', 'La Cache API y el tiered cache: cachear respuestas en el edge de forma programática; claves de cache, TTL, y purgado.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 27, 'Elegir storage', 'KV vs R2 vs D1 vs DO', 'El árbol de decisión del almacenamiento: KV (lecturas), R2 (objetos), D1 (SQL read-heavy), DO (estado coordinado), Hyperdrive (DB existente).', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 28, 'Workers AI', 'inferencia en el edge', 'Workers AI: ejecutar modelos (LLMs, embeddings, visión) sobre GPUs serverless con un binding; el catálogo de modelos y el patrón de inferencia.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 29, 'Vectorize', 'base de datos vectorial', 'Vectorize: una base de datos de vectores para búsqueda semántica; crear índices, insertar embeddings, y consultar por similitud.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 30, 'AI Gateway', 'gobernar la IA', 'AI Gateway: un proxy para tus llamadas a LLMs (propios o de terceros) con cache, rate limiting, reintentos, logs y analítica de coste.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 31, 'RAG en Cloudflare', 'el stack de IA', 'Montar Retrieval-Augmented Generation end-to-end: embeddings con Workers AI, búsqueda en Vectorize, contexto en D1/R2, y respuesta con un LLM.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 32, 'Agents y Workflows', 'IA con estado', 'El Agents SDK sobre Durable Objects y Workflows: agentes de IA con estado persistente, herramientas, y procesos de varios pasos resilientes.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 33, 'Pages', 'el legado', 'Cloudflare Pages: qué es, cómo funcionaba (frontend + Functions), y por qué en 2026 está en modo mantenimiento con todo lo nuevo yendo a Workers.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 34, 'De Pages a Workers', 'la convergencia', 'La convergencia de 2026: Workers alcanza paridad con Pages; migrar un proyecto de Pages a Workers, y por qué empezar directamente en Workers.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 35, 'Zero Trust y Access', 'proteger la app', 'Seguridad de plataforma: Cloudflare Access (autenticar antes de llegar a la app), Zero Trust, y WAF/rate limiting delante del Worker.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 36, 'Images y Stream', 'medios en el edge', 'Cloudflare Images (transformar y servir imágenes) y Stream (vídeo bajo demanda y en directo); descargar el peso de los medios al edge.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 37, 'Email, Turnstile, Rate Limiting', 'utilidades de borde', 'Piezas útiles: Email Workers (procesar correo entrante), Turnstile (CAPTCHA sin fricción), y el Rate Limiting nativo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 38, 'Wrangler avanzado', 'entornos y CI/CD', 'Wrangler a fondo: múltiples entornos, previews por rama, `wrangler.jsonc` a escala, y desplegar desde CI (GitHub Actions, Workers Builds).', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 39, 'Arquitectura full-stack', 'una app real en el edge', 'Ensamblar una app completa: Worker + assets + D1 + DO + Queues + Workers AI; el mapa de una arquitectura full-stack sobre Cloudflare.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 40, 'Rendimiento y costes', 'los límites del edge', 'Pensar como el edge: minimizar subrequests y CPU, cachear con criterio, entender el modelo de precios, y cuándo el edge NO es la respuesta.', NULL, NULL, NULL);
INSERT INTO level VALUES ('cloudflare', 41, 'Síntesis', 'la plataforma completa', 'La imagen total: cómo encajan compute, storage e IA en el edge; arquitecturas de referencia, trade-offs profundos, y hacia dónde va la plataforma.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 0, 'Ontología', 'El mapa del CSS moderno', 'La visión aérea: qué resuelve CSS, qué cambió entre 2020 y 2026, y el mapa mental de todo el territorio que vas a dominar.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 1, 'Qué es CSS de verdad', 'Un lenguaje declarativo de restricciones', 'CSS no ordena, sugiere restricciones que el motor resuelve. Entender esto cambia cómo escribes todo lo demás.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 2, 'La cascada', 'Origen, importancia, capas, especificidad', 'Los seis criterios reales de la cascada en orden, y por qué la especificidad es el penúltimo y no el primero.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 3, 'Especificidad', 'El sistema de tres números', 'Cómo se cuenta de verdad, por qué los IDs son una trampa, y cómo dejar de pelear con !important.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 4, 'Capas en cascada', '@layer y el control del orden', 'Declarar capas, importarlas, anidarlas y por qué una capa vence a la especificidad. La herramienta que faltaba.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 5, 'Herencia', 'inherit, initial, unset, revert', 'Qué se hereda y qué no, los cuatro valores globales, revert-layer, y el valor calculado frente al usado.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 6, 'Selectores modernos', ':is, :where y la especificidad cero', 'Agrupar sin inflar la especificidad, :where como llave maestra del CSS de librería, y :not con listas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 7, 'El selector de padre', ':has() y lo que desbloquea', 'El selector relacional: estilar el contenedor según su contenido, el hermano anterior, y patrones que antes exigían JS.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 8, 'Selectores estructurales', 'nth-child of, rangos y estado', 'nth-child con of, los pseudo-clases de estado, :focus-visible frente a :focus, y :user-invalid.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 9, 'Anidamiento nativo', 'Nesting sin preprocesador', 'La sintaxis, el ampersand implícito, la regla del relative selector, y las diferencias reales con Sass.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 10, 'Ámbito de estilos', '@scope, raíz y límite', 'Acotar estilos a un subárbol con techo y suelo, el donut scope, y la proximidad como criterio de cascada.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 11, 'Custom properties', 'Variables que viven en la cascada', 'No son variables de preprocesador: se heredan, se recalculan y se pueden cambiar en runtime. El fallback y el truco del espacio.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 12, 'Propiedades tipadas', '@property y el registro', 'Registrar una custom property con sintaxis, herencia y valor inicial. Lo que desbloquea: animar gradientes y ángulos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 13, 'El modelo de caja', 'box-sizing, márgenes y colapso', 'Content-box frente a border-box, el colapso de márgenes con sus tres casos, y por qué gap lo elimina.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 14, 'Contextos de formato', 'BFC, IFC y el flujo normal', 'Qué es un formatting context, qué lo crea, y por qué explica el 80% de los bugs de layout que parecen magia.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 15, 'Dimensionar', 'Tamaños intrínsecos y extrínsecos', 'min-content, max-content, fit-content y el algoritmo de resolución de anchos. La base de todo layout que no se rompe.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 16, 'Flexbox: el algoritmo', 'Base, crecer, encoger', 'flex-basis, grow y shrink como un sistema, la trampa de flex:1, y min-width auto que rompe el overflow.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 17, 'Flexbox en la práctica', 'Alineación, orden y patrones', 'Los ejes, alinear con margin auto, wrap y sus límites, y los patrones canónicos: barra, media object, sticky footer.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 18, 'Grid I', 'El sistema de dos dimensiones', 'Filas, columnas, la unidad fr, repeat, minmax y el modelo de líneas frente al de celdas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 19, 'Grid II', 'Áreas, líneas nombradas, auto-placement', 'grid-template-areas, nombrar líneas, el algoritmo de colocación automática y grid-auto-flow dense.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 20, 'Subgrid', 'Heredar las pistas del padre', 'El problema que resuelve: alinear contenido entre tarjetas hermanas. Sintaxis, herencia de gaps y soporte real.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 21, 'Grid o Flex', 'El árbol de decisión', 'Cuándo cada uno, por qué no compiten, y los casos donde combinarlos es la respuesta correcta.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 22, 'Layouts intrínsecos', 'Responsive sin breakpoints', 'auto-fit frente a auto-fill, el patrón RAM, y layouts que se adaptan por contenido en vez de por viewport.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 23, 'Alineación unificada', 'La caja de alineación en todo', 'justify y align como sistema transversal, las propiedades place, y su llegada a bloque con align-content.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 24, 'Container queries', 'Consultar el contenedor, no la ventana', 'containment, container-type, container-name y por qué esto es el cambio más grande del layout en una década.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 25, 'Unidades de contenedor', 'cqw, cqi, cqmin y compañía', 'Dimensionar en relación al contenedor, y el patrón de componente verdaderamente portable.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 26, 'Container style queries', 'Consultar custom properties', 'La función style sobre custom properties, el soporte real en 2026, y los patrones que ya funcionan hoy.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 27, 'Media queries modernas', 'Rangos y consultas de usuario', 'La sintaxis de rango, prefers-reduced-motion, prefers-color-scheme, prefers-contrast y las de puntero.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 28, 'Soporte y degradación', '@supports y las capas de fallback', 'Detectar features, comprobar selectores, y la estrategia de escribir el fallback primero.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 29, 'Unidades', 'px, em, rem, ch, lh, vi, dvh', 'El catálogo completo: las relativas al tipo, las lógicas, y por qué dvh existe y svh es distinto.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 30, 'Escalas fluidas', 'clamp() y la tipografía que respira', 'La matemática de clamp con viewport, construir una escala modular, y el problema de accesibilidad al hacer zoom.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 31, 'Fuentes web', '@font-face, subsetting, font-display', 'Cargar sin FOIT ni FOUT, unicode-range, preload, y el coste real de cada peso.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 32, 'Fuentes variables', 'Ejes y font-variation-settings', 'Un archivo, infinitos pesos: los ejes registrados y personalizados, y cuándo sale a cuenta.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 33, 'Detalles tipográficos', 'text-wrap, hyphens, features', 'text-wrap balance y pretty, hyphens, font-feature-settings, y el ajuste óptico del texto.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 34, 'Color I', 'sRGB, gamma y el problema', 'Por qué el degradado de azul a amarillo pasa por gris, qué es la gamma, y los límites de hex y hsl.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 35, 'Color II', 'OKLCH y los espacios perceptuales', 'Lightness, chroma y hue de verdad: por qué OKLCH permite paletas consistentes que hsl nunca pudo dar.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 36, 'Color III', 'color-mix, colores relativos, gamut', 'Mezclar en el espacio que elijas, derivar colores con from, y el mapeo de gamut a P3 y a sRGB.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 37, 'Gradientes', 'Interpolación, ángulos y cónicos', 'Lineales, radiales y cónicos, elegir el espacio de interpolación, y los degradados que no se ensucian.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 38, 'Fondos y bordes', 'Capas, repetición y radios', 'El modelo de capas de background, background-clip, los radios elípticos y border-image.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 39, 'Sombras y profundidad', 'box-shadow, drop-shadow, elevación', 'La diferencia real entre box-shadow y el filtro drop-shadow, y construir un sistema de elevación creíble.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 40, 'Recorte y máscaras', 'clip-path, mask, shape-outside', 'Recortar con formas y rutas, enmascarar con imágenes y gradientes, y hacer que el texto fluya alrededor.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 41, 'Filtros y fusión', 'filter, backdrop-filter, blend modes', 'El pipeline de filtros, el coste de backdrop-filter, y mix-blend-mode con los grupos de aislamiento.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 42, 'Transformaciones', 'El pipeline 2D y 3D', 'Las propiedades individuales, el orden de las matrices, transform-origin, perspective y transform-style.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 43, 'Contextos de apilamiento', 'z-index y por qué no funciona', 'Qué crea un stacking context, la jerarquía real, y por qué tu z-index de 9999 sigue quedando debajo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 44, 'Posicionamiento', 'De static a fixed, y el bloque contenedor', 'Los cinco valores, qué es el containing block de cada uno, y cómo transform rompe a fixed.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 45, 'Sticky', 'Cómo funciona de verdad', 'Las tres condiciones que debe cumplir, por qué falla con overflow hidden, y los patrones de cabecera pegajosa.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 46, 'Anchor positioning', 'Anclar sin JavaScript', 'anchor-name, position-anchor, la función anchor, position-try y el fallback cuando no cabe.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 47, 'La capa superior', 'dialog, popover y el top layer', 'El elemento dialog modal, el atributo popover, light dismiss, y por qué el top layer mata al z-index.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 48, 'Scroll', 'Snap, overscroll y barras', 'scroll-snap como sistema, scroll-behavior, overscroll-behavior, scrollbar-gutter y scroll-margin.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 49, 'Formularios', 'Estilar lo inestilizable', 'accent-color, field-sizing, appearance, el select personalizable, y los pseudo-elementos de cada control.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 50, 'Arquitectura I', 'De BEM a los tokens de diseño', 'La historia de las metodologías, qué problema resolvía cada una, y por qué los tokens ganaron.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 51, 'Arquitectura II', 'Utility-first, CSS-in-JS y el estado del arte', 'Tailwind y su modelo, el declive del CSS-in-JS en runtime, y qué eligen los equipos en 2026.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 52, 'Sistemas de diseño en CSS', 'Tokens, temas y modo oscuro', 'Construir una capa de tokens en tres niveles, temas con light-dark, y color-scheme.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 53, 'Rendimiento del CSS', 'contain, content-visibility y el coste', 'Qué cuesta caro de verdad, contain y sus tipos, content-visibility, will-change y cuándo NO usarlo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 54, 'Depurar CSS', 'Las herramientas y el método', 'El panel de estilos, los overlays de grid y flex, la cascada computada, y un método para bugs de layout.', NULL, NULL, NULL);
INSERT INTO level VALUES ('css', 55, 'Síntesis', 'Síntesis del CSS moderno', 'La arquitectura completa de una hoja de estilos de 2026, el mapa de decisiones, y hacia dónde va el lenguaje.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 0, 'Ontología', 'El mapa de las DevTools', 'Los paneles, qué problema resuelve cada uno, y el mapa mental para saber a cuál ir según el síntoma.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 1, 'Abrir y configurar', 'Atajos, docking y ajustes', 'Los atajos que ahorran horas, el command menu, el docking, los experimentos y sincronizar tus ajustes.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 2, 'Elements I', 'El árbol del DOM en vivo', 'Navegar y editar el DOM, el breadcrumb, buscar con selectores y XPath, y forzar estados de pseudo-clase.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 3, 'Elements II', 'El panel de estilos', 'Leer la cascada real, las reglas tachadas, editar en vivo, los valores computados y de dónde viene cada uno.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 4, 'Elements III', 'Overlays de layout', 'El inspector de grid y flex, las guías de alineación, el overlay de scroll-snap y el de container queries.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 5, 'Elements IV', 'Accesibilidad en el inspector', 'El árbol de accesibilidad, las propiedades ARIA computadas, el contraste con APCA y la simulación de visión.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 6, 'Console I', 'Más que console.log', 'table, group, dir, count, time, trace y assert, el formato con estilos, y los niveles de log.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 7, 'Console II', 'Utilidades y contexto', 'Las funciones de la consola, el selector de contexto, los live expressions, y las preservación del log.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 8, 'Sources I', 'Depurar con breakpoints', 'Los tipos de breakpoint, condicionales, logpoints, el paso a paso y leer el call stack.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 9, 'Sources II', 'Breakpoints sin línea', 'Breakpoints de evento, de DOM, de XHR y de excepción: cómo cazar un bug cuando no sabes dónde poner el punto.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 10, 'Sources III', 'Scope, watch y el async stack', 'Inspeccionar el scope, las expresiones vigiladas, la pila asíncrona completa y el blackboxing de librerías.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 11, 'Sources IV', 'Source maps y overrides', 'Cómo funcionan los source maps, depurar TypeScript, los local overrides para editar producción, y el workspace.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 12, 'Snippets', 'Tu caja de herramientas', 'Guardar y ejecutar scripts en cualquier página, los casos de uso reales, y una colección de snippets útiles.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 13, 'Network I', 'Leer el waterfall', 'Las columnas que importan, el desglose del timing, la cascada, y diagnosticar por la forma del waterfall.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 14, 'Network II', 'Filtrar, bloquear y simular', 'Los filtros avanzados, bloquear peticiones, el throttling de red, y desactivar la caché con criterio.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 15, 'Network III', 'Cabeceras, caché y seguridad', 'Leer las cabeceras de caché, diagnosticar un CORS, el panel de seguridad, y el HAR para compartir.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 16, 'Performance I', 'Grabar y leer un perfil', 'Grabar bien, las pistas del timeline, el flame chart, el main thread y encontrar la long task.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 17, 'Performance II', 'Las métricas en vivo', 'La pista de Core Web Vitals, el desglose de LCP e INP en el propio perfil, y los insights automáticos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 18, 'Performance III', 'Diagnóstico por síntoma', 'El árbol de decisión: si el patrón es este, mira allá. Los perfiles típicos de cada tipo de problema.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 19, 'Rendering', 'Los overlays de depuración', 'Paint flashing, layout shift regions, layer borders, FPS meter, y forzar los prefers y la emulación.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 20, 'Memory I', 'El heap snapshot', 'Tomar un snapshot, retained frente a shallow size, el retainer path, y encontrar qué mantiene vivo un objeto.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 21, 'Memory II', 'Cazar una fuga', 'La técnica de los tres snapshots, la línea de allocation timeline, los detached nodes y el ciclo de reproducción.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 22, 'Application', 'Almacenamiento y manifiesto', 'localStorage, IndexedDB, cookies, cache storage, el manifiesto y la cuota de almacenamiento.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 23, 'Service Workers en DevTools', 'Depurar el SW', 'El estado del worker, forzar la actualización, el modo offline, inspeccionar la cache y los eventos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 24, 'Animations', 'El panel de animaciones', 'Capturar, inspeccionar y editar animaciones en vivo, ralentizarlas, y ajustar las curvas visualmente.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 25, 'Lighthouse', 'La auditoría automática', 'Qué mide y cómo, la diferencia con el campo, leer el informe sin obsesionarse con el número, y el treemap.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 26, 'Coverage y CSS overview', 'Encontrar el código muerto', 'El panel de cobertura para CSS y JS no usado, sus límites reales, y la vista general del CSS del sitio.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 27, 'Depurar en móvil', 'Dispositivo real y emulación', 'La emulación de dispositivo y sus límites, el remote debugging por USB, y el port forwarding.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 28, 'Protocolo y automatización', 'CDP y Puppeteer', 'El Chrome DevTools Protocol por debajo, el panel de recorder, exportar a Puppeteer y automatizar auditorías.', NULL, NULL, NULL);
INSERT INTO level VALUES ('devtools', 29, 'El método de depuración', 'Síntesis y el método de depuración', 'El flujo completo de diagnóstico, la tabla síntoma-panel-acción, y los hábitos que separan al que depura rápido.', NULL, NULL, NULL);
INSERT INTO level VALUES ('elm', 0, 'Ontología', 'El mapa de Elm', 'La visión aérea: el lenguaje funcional puro, la arquitectura TEA, los efectos como datos, y el legado que sembró en Redux, TCA y MVI.', NULL, NULL, NULL);
INSERT INTO level VALUES ('elm', 1, 'The Elm Architecture', 'Model, update, view', 'TEA: el patrón que inspiró a todos; Model, Msg, update y view; la fuente de la familia unidireccional.', NULL, NULL, NULL);
INSERT INTO level VALUES ('elm', 2, 'Elm: efectos', 'commands y subscriptions', 'Cómo Elm maneja lo impuro sin romper la pureza: Cmd, Sub, y el runtime que ejecuta los efectos por ti.', NULL, NULL, NULL);
INSERT INTO level VALUES ('elm', 3, 'El lenguaje: tipos', 'estáticos e inferidos', 'El sistema de tipos de Elm: inferencia total, sin null, sin any; por qué el compilador puede garantizar tanto.', NULL, NULL, NULL);
INSERT INTO level VALUES ('elm', 4, 'Custom types', 'uniones y pattern matching', 'Los custom types (uniones etiquetadas) y `case`: modelar el dominio para que los estados imposibles no compilen.', NULL, NULL, NULL);
INSERT INTO level VALUES ('elm', 5, 'Maybe y Result', 'sin excepciones', 'La ausencia y el fallo como valores: `Maybe` y `Result`, y por qué Elm no tiene excepciones en runtime.', NULL, NULL, NULL);
INSERT INTO level VALUES ('elm', 6, 'Funciones', 'currying y composición', 'Todo es una función: aplicación parcial, currying, el operador pipe, y componer transformaciones pequeñas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('elm', 7, 'Records', 'datos inmutables', 'Records: acceso, actualización inmutable, extensible records, y modelar el Model de la aplicación.', NULL, NULL, NULL);
INSERT INTO level VALUES ('elm', 8, 'El compilador amigo', 'errores que enseñan', 'El compilador de Elm como copiloto: mensajes de error legendarios, refactor sin miedo, y cero errores en producción.', NULL, NULL, NULL);
INSERT INTO level VALUES ('elm', 9, 'HTML como función', 'la vista pura', 'elm/html: la vista es una función pura de Model a Html Msg; virtual DOM, eventos, y atributos tipados.', NULL, NULL, NULL);
INSERT INTO level VALUES ('elm', 10, 'Decodificadores JSON', 'datos del exterior', 'Decoders: validar y tipar los datos que entran desde el exterior; por qué Elm no confía en el JSON crudo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('elm', 11, 'Ports e interop', 'hablar con JavaScript', 'Ports: la frontera segura con JavaScript; enviar y recibir mensajes sin romper las garantías del compilador.', NULL, NULL, NULL);
INSERT INTO level VALUES ('elm', 12, 'Aplicaciones grandes', 'componer módulos', 'Escalar TEA: componer Model/Msg/update de submódulos, y por qué Elm evita los "componentes" al estilo React.', NULL, NULL, NULL);
INSERT INTO level VALUES ('elm', 13, 'Routing y SPA', 'Browser.application', 'Aplicaciones de una página en Elm: `Browser.application`, parsear la URL, y la navegación como parte del Model.', NULL, NULL, NULL);
INSERT INTO level VALUES ('elm', 14, 'Testing en Elm', 'puro es testeable', 'elm-test: testear funciones puras, fuzz testing (basado en propiedades), y testear update sin montar la vista.', NULL, NULL, NULL);
INSERT INTO level VALUES ('elm', 15, 'Estilos y UI', 'elm-ui y CSS', 'Construir interfaces: CSS clásico, elm-css, y elm-ui (el layout como tipos); el enfoque declarativo del diseño.', NULL, NULL, NULL);
INSERT INTO level VALUES ('elm', 16, 'Rendimiento', 'el runtime de Elm', 'Cómo funciona por dentro: el virtual DOM de Elm, Html.lazy, keyed nodes, y por qué los bundles salen pequeños.', NULL, NULL, NULL);
INSERT INTO level VALUES ('elm', 17, 'Elm en producción', 'build y despliegue', 'Llevar Elm a producción: el compilador, optimizaciones, integración con Vite/webpack, y convivir con una app JS.', NULL, NULL, NULL);
INSERT INTO level VALUES ('elm', 18, 'La filosofía', 'cero errores en runtime', 'La apuesta de Elm: garantías del compilador, versionado semántico forzado por tipos, y la estabilidad como valor.', NULL, NULL, NULL);
INSERT INTO level VALUES ('elm', 19, 'Elm frente al ecosistema', 'trade-offs honestos', 'La comparación sincera: qué gana Elm frente a TypeScript/React y qué pierde (ecosistema, contratación, ritmo de cambio).', NULL, NULL, NULL);
INSERT INTO level VALUES ('elm', 20, 'El legado de Elm', 'lo que sembró', 'Cómo TEA fecundó Redux, The Composable Architecture, MVI y hasta el diseño de Svelte; las ideas que se quedaron.', NULL, NULL, NULL);
INSERT INTO level VALUES ('elm', 21, 'Síntesis', 'pensar funcionalmente', 'La síntesis: llevar el pensamiento de Elm (pureza, efectos como datos, modelar el dominio) a cualquier lenguaje.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 0, 'Ontología', 'El mapa del estado', 'La visión aérea de la reactividad: primitivos, derivación, inmutabilidad, el estado del servidor y las arquitecturas. El mapa mental de toda la categoría.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 1, 'Qué es el estado', 'la raíz de la complejidad', 'Qué es "estado" y por qué es la mayor fuente de complejidad en una app; estado esencial vs accidental, y la meta de domarlo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 2, 'Taxonomía del estado', 'local, global, servidor, URL', 'Las clases de estado: local de UI, global de cliente, del servidor (cache), de la URL, y de formularios; cada una pide una herramienta distinta.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 3, 'Primitivos de reactividad', 'observer y pub/sub', 'Los cimientos: el patrón observer, pub/sub, y cómo un cambio propaga a quien lo escucha; la base de todo sistema reactivo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 4, 'Signals', 'el modelo y TC39', 'Signals: getter/setter con tracking automático de dependencias; el modelo, su auge en 2026, y el TC39 Signals proposal.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 5, 'Observables', 'RxJS y streams', 'El modelo push de los observables: streams de eventos en el tiempo, operadores, y RxJS; cuándo un stream y cuándo un signal.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 6, 'Derivación', 'memos y selectores', 'Estado derivado: valores computados a partir de otros (memos, selectores), memoización, y por qué derivar es mejor que duplicar.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 7, 'Inmutabilidad', 'structural sharing', 'Por qué la inmutabilidad domina el estado: comparación por referencia, structural sharing, Immer, y el coste real de copiar.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 8, 'El problema de sincronizar', 'glitches y consistencia', 'La dificultad central de la reactividad: glitches, estados intermedios inconsistentes, orden de actualización, y la propagación glitch-free.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 9, 'Estado del servidor', 'TanStack Query, SWR', 'El estado del servidor NO es estado de cliente: es una cache. TanStack Query y SWR; fetching, cache, revalidación, y por qué separarlo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 10, 'Estado en la URL', 'el router como estado', 'La URL como fuente de verdad: search params, deep linking, estado compartible y navegable; cuándo el estado debe vivir en la URL.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 11, 'Formularios como estado', 'el caso difícil', 'Los formularios son estado complejo: valores, validación, dirty/touched, envío; librerías (React Hook Form, TanStack Form) y el enfoque no controlado.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 12, 'Actualizaciones optimistas', 'sincronizar con el servidor', 'Optimistic updates: mostrar el resultado esperado antes de la confirmación y revertir si falla; reconciliar el estado local con el del servidor.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 13, 'Persistencia y offline', 'hidratación y estado local', 'Persistir el estado (localStorage, IndexedDB), hidratarlo al arrancar, y el estado offline; los peligros de la hidratación en SSR.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 14, 'La familia unidireccional', 'Redux, Elm, TCA, MVI', 'Comparar los primos: Redux, Elm, TCA y MVI comparten el ADN unidireccional; qué los une, qué los diferencia, y qué aprender de cada uno.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 15, 'Elegir arquitectura', 'el árbol de decisión', 'El criterio unificado: signals vs store vs máquina vs arquitectura formal; separar estado de servidor, cliente y UI; el árbol de decisión completo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 16, 'Local-first y CRDTs', 'el futuro del estado', 'Local-first: CRDTs (Yjs, Automerge), sincronización sin conflictos, y motores como Electric/Zero; el estado que vive en el cliente y converge.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 17, 'Event sourcing y CQRS', 'el estado como log', 'Guardar los eventos en vez del estado: event sourcing, proyecciones, CQRS, y por qué el log es la fuente de verdad definitiva.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 18, 'Undo, redo y time travel', 'historia del estado', 'Implementar deshacer/rehacer: pilas de estados, comandos inversos, y el time-travel debugging que habilita la inmutabilidad.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 19, 'Estado colaborativo', 'tiempo real y presencia', 'Varios usuarios sobre el mismo estado: OT vs CRDT, presencia, cursores, y resolver conflictos en tiempo real.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 20, 'Estado en SSR', 'serializar e hidratar', 'El estado que cruza del servidor al cliente: serialización, hidratación, mismatches, y el estado por petición sin filtrar entre usuarios.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 21, 'Tipar el estado', 'hacer imposible lo inválido', 'TypeScript al servicio del estado: uniones discriminadas, estados imposibles no representables, y validación con Zod en las fronteras.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 22, 'Testing del estado', 'lógica sin UI', 'Testear la lógica de estado aislada de la vista: reducers puros, máquinas, stores, y el testing basado en propiedades y en modelos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 23, 'Depurar la reactividad', 'por qué no se actualiza', 'El arte de depurar estado: DevTools, trazar el grafo de dependencias, y los diagnósticos de "no reacciona" o "reacciona de más".', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 24, 'Rendimiento del estado', 'el coste de reaccionar', 'Medir y optimizar: granularidad de las suscripciones, re-renders innecesarios, memoización, y el coste real de cada modelo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 25, 'Concurrencia y estado', 'carreras y transiciones', 'Estado y asincronía: condiciones de carrera lógicas, cancelar peticiones obsoletas, transiciones concurrentes, y la última escritura gana.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 26, 'Anti-patrones', 'síntomas y refactor', 'Los errores clásicos: estado duplicado, todo en global, estado derivado guardado, y el catálogo de refactors que los curan.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 27, 'Estado a escala', 'equipos y dominios', 'Organizar el estado en una app grande: fronteras por dominio, estado de feature vs compartido, y convenciones que sobreviven al equipo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 28, 'El futuro de la reactividad', 'hacia dónde va', 'Lo que viene: signals estandarizados en el lenguaje, async transparente, local-first por defecto, y la convergencia entre frameworks.', NULL, NULL, NULL);
INSERT INTO level VALUES ('estado', 29, 'Síntesis', 'la teoría del estado', 'La teoría unificada: todo estado es reactividad + una disciplina de mutación; conectar signals, máquinas y arquitecturas en un solo modelo mental.', NULL, NULL, NULL);
INSERT INTO level VALUES ('flux', 0, 'Ontología', 'El mapa de Flux', 'La visión aérea: el flujo unidireccional, Redux y su toolkit, el middleware, los selectores y la ola ligera (Zustand, Jotai).', NULL, NULL, NULL);
INSERT INTO level VALUES ('flux', 1, 'El patrón Flux', 'flujo unidireccional', 'Flux: el flujo de datos en una sola dirección; por qué Facebook lo creó y qué problema del MVC resolvió.', NULL, NULL, NULL);
INSERT INTO level VALUES ('flux', 2, 'Redux', 'store, actions, reducers', 'Redux: un único store inmutable, actions que describen qué pasó, y reducers puros; los tres principios.', NULL, NULL, NULL);
INSERT INTO level VALUES ('flux', 3, 'Redux Toolkit', 'slices y RTK Query', 'Redux Toolkit: createSlice, Immer integrado, createAsyncThunk, y RTK Query para el estado del servidor.', NULL, NULL, NULL);
INSERT INTO level VALUES ('flux', 4, 'Middleware y efectos', 'thunk, saga, listener', 'Los side effects en Redux: thunks, sagas, y el listener middleware; dónde vive lo asíncrono.', NULL, NULL, NULL);
INSERT INTO level VALUES ('flux', 5, 'Selectores', 'reselect y normalización', 'Leer el store con eficiencia: selectores memoizados, estado normalizado, y createEntityAdapter.', NULL, NULL, NULL);
INSERT INTO level VALUES ('flux', 6, 'El post-Redux', 'Zustand, Jotai, Valtio', 'La nueva ola ligera: Zustand, Jotai y Valtio; por qué Redux cayó del 57% al 38% de uso.', NULL, NULL, NULL);
INSERT INTO level VALUES ('flux', 7, 'Cuándo Redux', 'y las alternativas', 'El criterio en 2026: RTK para equipos grandes; Zustand para lo simple; y el patrón dominante con TanStack Query.', NULL, NULL, NULL);
INSERT INTO level VALUES ('flux', 8, 'Redux DevTools', 'time travel real', 'Las DevTools: inspeccionar cada acción, viajar en el tiempo, exportar sesiones, y por qué esto sedujo a una generación.', NULL, NULL, NULL);
INSERT INTO level VALUES ('flux', 9, 'RTK Query a fondo', 'cache y tags', 'RTK Query en serio: endpoints, tags de invalidación, transformaciones, polling, y comparación con TanStack Query.', NULL, NULL, NULL);
INSERT INTO level VALUES ('flux', 10, 'redux-saga a fondo', 'efectos con generadores', 'Sagas: los efectos como objetos declarativos, take/put/call/fork, cancelación, y orquestar flujos complejos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('flux', 11, 'Testing de Redux', 'reducers y efectos', 'Testear el estado: reducers puros (trivial), thunks, sagas con su runner, y tests de integración con el store real.', NULL, NULL, NULL);
INSERT INTO level VALUES ('flux', 12, 'Estructura a escala', 'ducks y features', 'Organizar un Redux grande: el patrón ducks, carpetas por feature, y las fronteras entre slices.', NULL, NULL, NULL);
INSERT INTO level VALUES ('flux', 13, 'TypeScript en Redux', 'tipar el store', 'Tipar Redux correctamente: RootState, AppDispatch, hooks tipados, y la inferencia que RTK regala.', NULL, NULL, NULL);
INSERT INTO level VALUES ('flux', 14, 'Zustand a fondo', 'el store minimalista', 'Zustand en serio: create, slices, middleware (persist, immer, devtools), selectores y el patrón de acciones.', NULL, NULL, NULL);
INSERT INTO level VALUES ('flux', 15, 'Jotai a fondo', 'estado atómico', 'Jotai: átomos primitivos y derivados, atomFamily, atomWithStorage, suspense, y el modelo bottom-up.', NULL, NULL, NULL);
INSERT INTO level VALUES ('flux', 16, 'Valtio y nanostores', 'proxy y agnóstico', 'Valtio (proxy mutable reactivo) y nanostores (diminuto y agnóstico del framework); sus nichos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('flux', 17, 'Migrar de Redux', 'a Zustand o RTK', 'Estrategias de migración incremental: convivir dos stores, migrar slice a slice, y cuándo NO migrar.', NULL, NULL, NULL);
INSERT INTO level VALUES ('flux', 18, 'Redux fuera de React', 'agnóstico de vista', 'Redux con Vue, Angular, Svelte o vanilla; y el eco del patrón en otras plataformas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('flux', 19, 'Rendimiento', 'evitar re-renders', 'El coste de un store global: suscripciones granulares, selectores con igualdad, y diagnosticar renders de más.', NULL, NULL, NULL);
INSERT INTO level VALUES ('flux', 20, 'Persistencia', 'guardar y rehidratar', 'Persistir el store (redux-persist, el middleware persist de Zustand): qué guardar, migraciones de versión y SSR.', NULL, NULL, NULL);
INSERT INTO level VALUES ('flux', 21, 'Patrones avanzados', 'undo, optimista, entity', 'Patrones que el flujo unidireccional hace fáciles: undo/redo, actualizaciones optimistas y colecciones normalizadas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('flux', 22, 'Errores comunes', 'y cómo salir', 'Los pecados clásicos: mutar el estado, poner todo en global, guardar datos derivados, y el remedio de cada uno.', NULL, NULL, NULL);
INSERT INTO level VALUES ('flux', 23, 'Síntesis', 'el legado de Flux', 'La síntesis: qué aportó Flux al pensamiento sobre estado, qué sobrevive en 2026, y cómo elegir con criterio.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 0, 'Ontología', 'El mapa del desarrollo iOS', 'La visión aérea: SwiftUI y el modelo declarativo, los datos, la arquitectura de una app, las capacidades del sistema y el camino a la App Store.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 1, 'SwiftUI esencial', 'vistas y estado', 'Construir interfaces declarativas: vistas, layout, modificadores, estado con @State y @Binding, listas y navegación.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 2, 'SwiftUI avanzado', '@Observable y animaciones', 'Llevar SwiftUI al límite: @Observable, environment, animaciones, gestos, dibujo y las APIs nuevas de iOS 26.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 3, 'SwiftData', 'persistencia moderna', 'Persistencia con SwiftData: @Model, @Query, relaciones, herencia de modelos, migraciones y sincronización con CloudKit.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 4, 'De la idea a la App Store', 'el panorama completo', 'El recorrido entero de una app: arquitectura, inyección de dependencias, testing, accesibilidad, localización y publicación.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 5, 'El sistema de layout', 'cómo mide SwiftUI', 'El algoritmo de layout: la negociación padre-hijo, prioridades, `frame`, `alignmentGuide` y escribir un `Layout` propio.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 6, 'Listas y colecciones', 'rendimiento y edición', 'Listas a fondo: `List` vs `LazyVStack`, secciones, swipe actions, edición, refresco y el coste real del scroll.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 7, 'Navegación', 'NavigationStack y rutas', 'La navegación moderna: `NavigationStack`, rutas tipadas, `NavigationSplitView`, deep links y restaurar la sesión.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 8, 'Formularios y entrada', 'texto, foco y validación', 'Entrada de datos: `TextField`, foco programático, teclado, validación en vivo y formularios accesibles.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 9, 'Animaciones a fondo', 'transiciones y física', 'Animaciones avanzadas: `withAnimation`, transiciones personalizadas, `matchedGeometryEffect`, `PhaseAnimator` y springs.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 10, 'Dibujo y gráficos', 'Canvas, Shape, Charts', 'Gráficos en SwiftUI: `Shape` y `Path`, `Canvas`, Metal shaders, y Swift Charts para visualización de datos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 11, 'Estado en SwiftUI', 'la fuente de la verdad', 'El sistema de estado: `@State`, `@Binding`, `@Environment`, `@Observable`; identidad de vistas y por qué a veces no se actualiza.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 12, 'Persistencia alternativa', 'Core Data, archivos, Keychain', 'Más allá de SwiftData: cuándo Core Data sigue mandando, guardar archivos, `UserDefaults` y secretos en el Keychain.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 13, 'Redes en apps', 'APIs y sincronización', 'Consumir APIs: `URLSession` con async/await, `Codable`, reintentos, cache, subidas y descargas en segundo plano.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 14, 'Imágenes y multimedia', 'fotos, audio, vídeo', 'Medios en una app: `AsyncImage`, PhotosPicker, la cámara, reproducir audio y vídeo con AVFoundation.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 15, 'Concurrencia en la UI', 'MainActor y tareas', 'Async en la interfaz: `.task`, cancelación al desaparecer la vista, `@MainActor`, y no bloquear nunca el hilo principal.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 16, 'Arquitectura de apps', 'patrones y capas', 'Estructurar una app real: MV vs MVVM vs TCA, capas de dominio y datos, y las fronteras que aguantan el crecimiento.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 17, 'Modularización', 'paquetes y fronteras', 'Dividir la app en módulos SPM: tiempos de compilación, previews aislados, y el grafo de dependencias sano.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 18, 'Testing de apps', 'unidad, UI y snapshots', 'Testear una app iOS: lógica con Swift Testing, tests de UI con XCUITest, snapshot testing y qué merece la pena.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 19, 'Accesibilidad', 'apps para todos', 'Accesibilidad de verdad: VoiceOver, Dynamic Type, contraste, reducción de movimiento, y auditar con el inspector.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 20, 'Localización', 'idiomas y regiones', 'Internacionalizar: String Catalogs, plurales, formatos de fecha y número, texto de derecha a izquierda y probar en varios idiomas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 21, 'Notificaciones', 'locales y push', 'Notificaciones: permisos, locales, push con APNs, contenido enriquecido, y las extensiones de servicio y contenido.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 22, 'Widgets y App Intents', 'fuera de la app', 'Extender la app al sistema: WidgetKit, Live Activities, App Intents, atajos de Siri y controles interactivos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 23, 'CloudKit y sincronización', 'datos entre dispositivos', 'Sincronizar: CloudKit con SwiftData, conflictos, compartir registros entre usuarios y trabajar sin conexión.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 24, 'Rendimiento de apps', 'arranque, memoria, batería', 'Que la app vuele: tiempo de arranque, uso de memoria, consumo de batería, scroll a 120fps y el coste de cada decisión.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 25, 'Instruments', 'medir de verdad', 'Depurar y perfilar: Instruments (Time Profiler, Allocations, Leaks), el debugger de vistas, y encontrar la causa real.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 26, 'Seguridad y privacidad', 'permisos y datos', 'Proteger al usuario: permisos y sus descripciones, App Tracking Transparency, manifiestos de privacidad, cifrado y Keychain.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 27, 'Distribución', 'TestFlight y App Store', 'Publicar: certificados y perfiles, App Store Connect, TestFlight, la revisión de Apple y los rechazos más comunes.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 28, 'Monetización', 'StoreKit 2', 'Ganar dinero: compras dentro de la app y suscripciones con StoreKit 2, verificar transacciones y probar con sandbox.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 29, 'Analítica y crashes', 'saber qué pasa', 'Observabilidad: métricas de MetricKit, informes de fallo, analítica respetuosa con la privacidad, y cerrar el bucle con el usuario.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 30, 'CI/CD para iOS', 'automatizar el ciclo', 'Automatizar: Xcode Cloud o GitHub Actions, firmar en CI, subir a TestFlight sola, y los tests en cada pull request.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 31, 'Más allá del iPhone', 'iPad, Mac, watch, visionOS', 'Una base de código, muchas pantallas: adaptar a iPad, llevar a Mac con Catalyst o nativo, watchOS y visionOS.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 32, 'UIKit', 'lo que sigue vivo', 'UIKit en 2026: cuándo sigue siendo necesario, el ciclo de vida de un controlador, y qué conceptos conviene conocer.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 33, 'Interoperar UIKit', 'los dos mundos', 'Mezclar frameworks: `UIViewRepresentable`, `UIHostingController`, y migrar una app de UIKit a SwiftUI pantalla a pantalla.', NULL, NULL, NULL);
INSERT INTO level VALUES ('ios', 34, 'Síntesis', 'construir y sostener', 'La síntesis: arquitectar una app completa, sostenerla en el tiempo, y hacia dónde va el desarrollo en el ecosistema Apple.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 0, 'Ontología', 'El mapa del kernel', 'La visión aérea del kernel: subsistemas, cómo se relacionan, y el mapa mental de todo lo que vas a dominar.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 1, 'Qué es un kernel', 'Anillos, monolítico vs micro', 'El rol del kernel, espacio usuario vs kernel, la cadena de arranque y por qué Linux domina.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 2, 'El C del kernel', 'Freestanding, sin libc', 'GNU C, freestanding, sin libc, y el arsenal de macros (container_of) que define el kernel.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 3, 'El árbol de fuentes', 'Estructura y git', 'Navegar millones de líneas: estructura de directorios y usar git para entender el porqué.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 4, 'Configurar (Kconfig)', 'menuconfig, y/m/n', 'El sistema de configuración, escribir tus propias entradas Kconfig, y depends on vs select.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 5, 'Compilar (Kbuild)', 'Imagen, módulos, obj-m', 'El sistema de build del kernel y el Makefile de tu módulo out-of-tree.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 6, 'Laboratorio (QEMU)', 'VM segura y gdb', 'Montar un entorno seguro con QEMU y depurar el kernel en vivo con gdb.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 7, 'Tu primer módulo', 'LKM y ciclo de vida', 'module_init/exit, printk, y las herramientas del ciclo de vida de un módulo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 8, 'Parámetros y /sys', 'module_param, sysfs, debugfs', 'Exponer y controlar tu módulo como archivos: procfs, sysfs y debugfs.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 9, 'Estilo y calidad', 'coding style, checkpatch', 'El estilo estricto del kernel y las herramientas (checkpatch, sparse) que lo verifican.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 10, 'Estructuras de datos', 'list_head, rbtree, xarray', 'Las listas intrusivas, árboles rojo-negro, hashes y xarray que el kernel usa por todas partes.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 11, 'Errores del kernel', 'ERR_PTR, goto, -errno', 'ERR_PTR, el patrón goto de limpieza en cascada, y elegir bien los códigos de error.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 12, 'La frontera con el usuario', 'copy_*_user, capabilities', 'copy_to/from_user, por qué nunca confiar en el usuario, y el sistema de capabilities.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 13, 'Char devices', 'file_operations, read/write', 'Registrar un char device y darle vida con open, read, write e ioctl.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 14, 'Concurrencia y atomics', 'SMP, preempción, atomic_t', 'Por qué el kernel es concurrente por defecto, y las operaciones atómicas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 15, 'Spinlocks', 'spin_lock, irqsave, reglas', 'La sincronización que no duerme: spinlocks, irqsave, y las reglas de oro.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 16, 'Locks que duermen', 'mutex, rwsem, completion', 'Mutex, semáforos, rwsem y completions: sincronización en contexto que puede dormir.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 17, 'RCU', 'Read-Copy-Update', 'Lecturas sin bloqueo que escalan a miles de núcleos: grace periods, flavors y listas RCU.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 18, 'Memoria compartida y barreras', 'per-CPU, seqlock, memory model', 'per-CPU, seqlocks, el modelo de memoria del kernel y las barreras (smp_mb, acquire/release).', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 19, 'lockdep y deadlocks', 'depurar el locking', 'Cómo el kernel detecta deadlocks automáticamente y cómo depurar problemas de sincronización.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 20, 'El page allocator', 'buddy, órdenes, GFP', 'El asignador de páginas (buddy system), las órdenes de páginas y los flags GFP.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 21, 'slab y slub', 'kmalloc, caches de objetos', 'kmalloc/kfree por dentro: el slab allocator, slub, y crear tus propios caches (kmem_cache).', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 22, 'vmalloc y direcciones del kernel', 'el espacio virtual del kernel', 'vmalloc vs kmalloc, y el mapa del espacio de direcciones virtual del kernel.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 23, 'mmap y memoria de procesos', 'VMA, page faults', 'Cómo el kernel gestiona la memoria virtual de los procesos: VMA, page faults y demand paging.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 24, 'El page cache', 'address_space, E/S', 'Cómo el kernel cachea archivos en memoria y realiza la E/S a través del page cache.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 25, 'Reclaim y presión de memoria', 'LRU, kswapd, OOM', 'Cómo el kernel recupera memoria bajo presión: LRU, kswapd, swap y el OOM killer.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 26, 'NUMA y per-CPU', 'localidad y memoria por núcleo', 'Memoria no uniforme (NUMA), localidad, y estructuras de datos por CPU.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 27, 'DMA e IOMMU', 'transferencias a dispositivos', 'DMA coherente y streaming, direcciones de bus, y el IOMMU que protege la memoria.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 28, 'El device model', 'kobject, bus/class/driver', 'El modelo de dispositivos unificado: kobject, sysfs, y la tríada bus/class/driver.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 29, 'Platform y device tree', 'platform_driver, DT, probe', 'Dispositivos sin bus de descubrimiento: platform drivers, device tree y el ciclo probe/remove.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 30, 'PCI', 'config space, BAR, MSI', 'El bus PCI/PCIe a fondo: espacio de configuración, BARs, e interrupciones MSI/MSI-X.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 31, 'USB', 'URB, endpoints, drivers', 'La pila USB: endpoints, URBs, y escribir un driver USB.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 32, 'I2C, SPI y regmap', 'buses lentos, regmap', 'Los buses de dispositivos embebidos (I2C, SPI) y la abstracción regmap para registros.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 33, 'GPIO e IIO', 'pines, sensores, IRQ', 'Control de pines (GPIO), el subsistema de sensores (IIO), y mapear interrupciones de dispositivo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 34, 'Interrupciones a fondo', 'threaded IRQ, softirq, workqueue', 'Manejar interrupciones, el trabajo diferido (softirq, tasklet, workqueue) y threaded IRQ.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 35, 'El block layer', 'bio, request, blk-mq', 'La capa de bloques: bio, request queues, y la arquitectura multi-cola blk-mq.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 36, 'I/O schedulers y block drivers', 'mq-deadline, un block driver', 'Los planificadores de E/S (mq-deadline, BFQ, Kyber) y escribir un driver de bloques.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 37, 'VFS a fondo', 'superblock, inode, dentry, file', 'El Virtual File System por dentro: sus cuatro objetos y cómo abstrae cualquier sistema de archivos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 38, 'Escribir un filesystem', 'libfs, un FS en memoria', 'Registrar un sistema de archivos y construir uno mínimo en memoria con libfs.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 39, 'E/S multiplexada', 'select, poll, epoll', 'La E/S basada en readiness: select, poll, y epoll a fondo (el motor de la red de alto rendimiento).', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 40, 'io_uring', 'rings SQ/CQ', 'La interfaz de E/S asíncrona por anillos: submission/completion queues y el modelo de completado.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 41, 'io_uring avanzado', 'buffers registrados, liburing', 'Buffers y descriptores registrados, modos de sondeo, multishot y liburing.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 42, 'Zero-copy y mmap de drivers', 'DMA a userspace', 'Exponer memoria de dispositivo a userspace con mmap y técnicas de copia cero.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 43, 'La pila de red', 'sk_buff, net_device', 'El corazón del networking: sk_buff, net_device, y el viaje de un paquete por el kernel.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 44, 'NAPI, sockets y XDP', 'recepción, protocolos, fast path', 'La recepción eficiente (NAPI), la API de sockets por dentro, y el fast path con XDP/eBPF.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 45, 'Tiempo', 'jiffies, hrtimers, NO_HZ', 'Cómo el kernel mide y programa el tiempo: jiffies, hrtimers, clocksource y el modo tickless.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 46, 'El scheduler (EEVDF)', 'task_struct, context switch', 'El planificador moderno EEVDF, el task_struct, y la mecánica del cambio de contexto.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 47, 'SMP, RT y cgroups', 'balanceo, tiempo real, recursos', 'Balanceo de carga entre núcleos, scheduling de tiempo real y deadline, y control de recursos con cgroups.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 48, 'ftrace y tracepoints', 'seguir la ejecución', 'El function tracer, los tracepoints estáticos, y la infraestructura de trazado del kernel.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 49, 'kprobes y perf', 'sondas dinámicas, perfilado', 'Instrumentar cualquier función en caliente con kprobes, y perfilar el kernel con perf.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 50, 'eBPF', 'programas en el kernel', 'Ejecutar programas seguros dentro del kernel: el verifier, los mapas, y sus mil usos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 51, 'Sanitizers y depuración', 'KASAN, KCSAN, kgdb', 'Los sanitizers del kernel (KASAN, KCSAN, KMSAN), kmemleak, y depurar oops y panics.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 52, 'Aislamiento y seguridad', 'namespaces, cgroups, LSM', 'La base de los contenedores (namespaces, cgroups) y los módulos de seguridad (seccomp, LSM/SELinux).', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 53, 'Virtualización', 'KVM, virtio', 'Cómo el kernel es un hipervisor: KVM, y los drivers paravirtualizados virtio.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 54, 'Rust for Linux', 'el modelo, abstracciones', 'Por qué Rust entró en el kernel, cómo conviven Rust y C, y las abstracciones seguras.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 55, 'Un driver en Rust', 'un driver real y seguro', 'Escribir un driver completo en Rust for Linux, aprovechando su seguridad de memoria.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 56, 'Contribuir upstream', 'el proceso de parches', 'Preparar y enviar un parche: git format-patch, send-email, las listas y la revisión.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kernel', 57, 'Mantener y el futuro', 'ser maintainer, el futuro', 'El rol de mantenedor, sostener un subsistema, y hacia dónde va el kernel.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 0, 'Ontología', 'El mapa de Kotlin', 'La visión aérea del lenguaje: el sistema de tipos y la nulabilidad, las corrutinas, el compilador K2, los cuatro backends y el ecosistema multiplataforma.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 1, 'El lenguaje', 'quince años y un compilador nuevo', 'De dónde viene Kotlin, qué problema de Java resolvía, la reescritura del compilador con K2, y los objetivos de compilación que hoy soporta.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 2, 'Sintaxis esencial', 'todo es una expresión', 'La base: `val` frente a `var`, inferencia de tipos, `if` y `when` como expresiones, rangos, y por qué apenas hay sentencias en Kotlin.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 3, 'Funciones', 'la unidad de trabajo', 'Parámetros por defecto y nombrados, funciones de una expresión, funciones locales, `infix`, `vararg` y funciones de nivel superior.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 4, 'Null safety', 'el sistema de tipos contra el NPE', 'La nulabilidad en el tipo: `T` frente a `T?`, `?.`, `?:`, `!!`, smart casts, y los platform types que llegan desde Java.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 5, 'Clases y propiedades', 'estado con contrato', 'Constructor primario y secundarios, bloques `init`, propiedades con getter y setter, visibilidad, y por qué en Kotlin no se escriben campos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 6, 'Data classes', 'datos sin ceremonia', 'Qué genera una data class, `equals`/`hashCode`/`toString`/`copy`, el desestructurado posicional y el desestructurado por nombre de 2.3.20.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 7, 'Objetos y companion', 'singletons en el lenguaje', 'La palabra clave `object`: singletons, expresiones de objeto, `companion object`, factorías, y su representación real en el bytecode.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 8, 'Sealed y exhaustividad', 'modelar el dominio cerrado', 'Jerarquías cerradas: `sealed class` y `sealed interface`, `when` exhaustivo, y modelar estados imposibles fuera del sistema de tipos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 9, 'Interfaces y delegación', 'componer sin heredar', 'Interfaces con implementación por defecto, resolución de conflictos, y la delegación de implementación con `by` como alternativa a la herencia.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 10, 'Propiedades delegadas', 'interceptar el acceso', '`lazy`, `observable`, delegación a un mapa, escribir tu propio delegado, `lateinit`, y los explicit backing fields estables en 2.4.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 11, 'Extensiones', 'añadir sin tocar', 'Funciones y propiedades de extensión: resolución estática, el receptor, el ámbito de importación, y por qué no son inyección de métodos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 12, 'Lambdas', 'funciones como valores', 'Sintaxis de lambda, `it`, el último parámetro fuera de los paréntesis, referencias a función, y los tipos función por dentro.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 13, 'Funciones de scope', 'let, run, with, apply, also', 'Las cinco funciones que todo el mundo confunde: qué recibe cada una, qué devuelve, y un criterio claro para elegir sin dudar.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 14, 'inline y reified', 'el coste de abstraer', 'Por qué existe `inline`: eliminar la asignación de la lambda; `noinline`, `crossinline`, retornos no locales, y los genéricos `reified`.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 15, 'Genéricos y varianza', 'in, out y las estrellas', 'Parámetros de tipo, restricciones, varianza en el sitio de declaración (`in`/`out`) y en el de uso, proyecciones estrella, y el borrado de tipos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 16, 'Colecciones y secuencias', 'perezoso frente a ansioso', 'La jerarquía de solo lectura frente a mutable, los operadores de la stdlib, y cuándo una `Sequence` gana de verdad frente a una lista.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 17, 'Operadores y convenciones', 'sobrecarga por nombre', 'La sobrecarga de operadores por convención de nombres: `plus`, `get`, `invoke`, `componentN`, `compareTo`, iteradores y rangos propios.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 18, 'DSLs', 'lambdas con receptor', 'El mecanismo detrás de Gradle KTS y Compose: lambdas con receptor, builders con seguridad de tipos, `@DslMarker` y diseñar un DSL usable.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 19, 'Contratos y smart casts', 'lo que el compilador deduce', 'Cómo funciona el análisis de flujo que permite el smart cast, por qué falla con propiedades mutables, y los `contracts` de la stdlib.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 20, 'Context parameters', 'dependencias implícitas', 'Estables en 2.4: qué problema resuelven, en qué se diferencian de los context receivers que sustituyen, y cómo no abusar de ellos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 21, 'Errores', 'sin excepciones comprobadas', 'La decisión de eliminar las checked exceptions, `try` como expresión, `Result`, modelar el fallo con sealed classes, y el diseño en las fronteras.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 22, 'Corrutinas I', 'qué es suspender', 'El corazón del asunto: `suspend` como transformación del compilador, la `Continuation`, el estilo CPS, y por qué una corrutina no es un hilo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 23, 'Corrutinas II', 'concurrencia estructurada', '`CoroutineScope`, `Job` y la jerarquía padre-hijo; `launch` frente a `async`, la cancelación cooperativa y la propagación de errores.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 24, 'Corrutinas III', 'contexto y dispatchers', 'El `CoroutineContext` como mapa de elementos, los dispatchers y su pool, `withContext`, y el error de creer que el problema es el hilo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 25, 'Corrutinas IV', 'canales y select', 'Comunicación entre corrutinas: `Channel` y sus tipos de buffer, productores y consumidores, `select`, y el modelo CSP en Kotlin.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 26, 'Flow I', 'streams fríos', '`Flow` como stream frío: builders, operadores intermedios y terminales, la contrapresión que sale gratis, y el contrato de contexto.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 27, 'Flow II', 'StateFlow y flujos calientes', '`StateFlow` y `SharedFlow`: conflación, réplica, `shareIn` y `stateIn`, y la diferencia real entre un flujo frío y uno caliente.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 28, 'El compilador K2', 'frontend, IR y backends', 'Cómo compila Kotlin hoy: el frontend K2 y su árbol, la representación intermedia común, y por qué la reescritura desbloqueó el resto del ecosistema.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 29, 'Kotlin/JVM', 'la vista desde Java', 'Cómo se ve tu Kotlin desde Java: nombres, `@JvmStatic`, `@JvmName`, `@JvmOverloads`, nulabilidad en la frontera y las clases sintéticas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 30, 'Value classes', 'abstracción sin coste', 'Las clases de valor y el inline en el runtime: cuándo se elimina el envoltorio y cuándo hay boxing, y su uso para tipos de dominio.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 31, 'Anotaciones y reflexión', 'mirar el propio código', 'Definir anotaciones y sus targets, la reflexión de Kotlin frente a la de Java, la reflexión ligera, y el coste real de usarla.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 32, 'KSP y plugins', 'generar en vez de reflexionar', 'El procesamiento de símbolos con KSP frente al viejo kapt, escribir un procesador, y los plugins de compilador que ya usas sin saberlo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 33, 'Multiplataforma', 'expect y actual', 'El modelo de KMP: source sets y su jerarquía, `expect`/`actual`, qué se comparte de verdad, y el ciclo de compilación multiplataforma.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 34, 'Kotlin/Native', 'sin máquina virtual', 'La compilación nativa: el recolector 2.0 que enterró los objetos congelados, la interoperabilidad con C y Objective-C, y el export a Swift.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 35, 'Wasm y JS', 'los otros backends', 'Kotlin/Wasm con su propio modelo de memoria y compilación incremental, Kotlin/JS y su interoperabilidad, y qué esperar de cada uno.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 36, 'Testing', 'kotlin.test y corrutinas', 'Tests multiplataforma con `kotlin.test`, testear código suspendido con `runTest` y dispatchers de prueba, y el tiempo virtual.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 37, 'Diseño de API', 'compatibilidad binaria', 'Escribir una biblioteca: `explicit API mode`, qué rompe la compatibilidad binaria y no la de fuente, `@Deprecated` y las opt-in APIs.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 38, 'Rendimiento', 'dónde asigna Kotlin', 'El coste oculto: lambdas que asignan, boxing de primitivos y nullables, el escape analysis de la JVM, y cómo medir antes de optimizar.', NULL, NULL, NULL);
INSERT INTO level VALUES ('kotlin', 39, 'Síntesis', 'síntesis y el futuro', 'El modelo mental completo del lenguaje, cómo se decide una nueva característica en el proceso KEEP, leer la fuente del compilador y hacia dónde va.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 0, 'Ontología', 'El mapa de local-first', 'La visión aérea: los siete ideales, el almacenamiento del cliente, los CRDT, el almacenamiento por contenido, los motores de sincronización y la identidad sin servidor.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 1, 'Los siete ideales', 'qué promete de verdad', 'El artículo de Ink & Switch que fundó el término: rapidez, multidispositivo, offline, colaboración, longevidad, privacidad y control del usuario. Qué promete cada ideal y cuál se incumple más.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 2, 'No es offline-first', 'la taxonomía honesta', 'Offline-first, local-first, sync-first y app nativa no son sinónimos. Qué significa cada término, quién lo usa para vender y en qué se distinguen técnicamente.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 3, 'El coste del servidor', 'la latencia como diseño', 'Por qué la arquitectura cliente-servidor produce ruedas de carga: el viaje de ida y vuelta, el servidor como punto único de fallo, y el coste que nadie mide de la latencia acumulada.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 4, 'Propiedad del dato', 'el argumento no técnico', 'Longevidad, privacidad y control: qué pasa con tus datos cuando la empresa cierra, cambia de precio o de términos. El argumento que decide la arquitectura y no es de ingeniería.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 5, 'Cuándo NO hacerlo', 'el criterio inverso', 'Los casos donde local-first es la respuesta equivocada: autoridad central obligatoria, datos que no caben, permisos que cambian, cumplimiento normativo y equipos pequeños.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 6, 'El mapa del almacenamiento', 'cookies, local y session', 'Todo lo que el navegador ofrece para guardar: cookies, localStorage, sessionStorage y sus límites reales. Por qué los cinco megabytes de localStorage no son negociables.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 7, 'IndexedDB I', 'el modelo', 'Almacenes de objetos, índices, transacciones y cursores. El modelo mental de la única base de datos que todos los navegadores traen de serie.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 8, 'IndexedDB II', 'por qué es lento', 'Dónde se va el tiempo: la serialización estructurada, el coste por transacción, los patrones que lo hacen soportable y los envoltorios que valen la pena.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 9, 'OPFS I', 'el sistema de archivos del origen', 'El Origin Private File System: un sistema de archivos real, privado por origen, sin diálogos de permiso. Qué es, qué lo diferencia de la File System Access API y qué te da.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 10, 'OPFS II', 'la restricción que lo cambia todo', 'El acceso síncrono solo existe dentro de un Worker, y esa única restricción condiciona la arquitectura entera de tu aplicación. Por qué es así y cómo se convive con ello.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 11, 'Cuotas y desalojo', 'cuando el navegador te borra', 'El modelo de cuota por origen, el modo best-effort, el desalojo silencioso bajo presión de disco, y cómo pedir persistencia de verdad con la API de almacenamiento.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 12, 'SQLite en el navegador I', 'WASM y la capa VFS', 'La compilación oficial a WebAssembly, la arquitectura de VFS que hace posible enchufarle cualquier backend de almacenamiento, y qué significa tener SQL de verdad en el cliente.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 13, 'SQLite en el navegador II', 'sobre OPFS, y a qué precio', 'El VFS de OPFS, las alternativas de la comunidad, el rendimiento medido en bases de varios gigabytes y los modos de concurrencia que tienes que elegir.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 14, 'El catálogo de bases locales', 'y cómo elegir', 'RxDB, PouchDB, Dexie, TinyBase, DuckDB en WebAssembly y los almacenes de los propios motores de sync. Qué resuelve cada uno y con qué criterio se elige.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 15, 'Consultas reactivas', 'la UI que se entera sola', 'El problema de mantener la interfaz sincronizada con la base local: consultas vivas, invalidación, y por qué esto define la ergonomía de toda la aplicación.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 16, 'Web Workers I', 'el modelo de hilos de la web', 'Hilos reales sin memoria compartida: el paso de mensajes, el algoritmo de clonado estructurado, qué se puede transferir y qué se copia.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 17, 'Web Workers II', 'SharedWorker y las pestañas', 'El problema de las pestañas múltiples sobre la misma base de datos. SharedWorker, su soporte irregular, y las alternativas cuando no está disponible.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 18, 'Web Locks y liderazgo', 'quién escribe', 'La API de bloqueos del navegador, la elección de líder entre pestañas, y el patrón que evita que dos pestañas corrompan la misma base.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 19, 'La arquitectura de la pestaña', 'el patrón completo', 'Juntar las piezas: la base en un Worker dedicado, RPC tipado sobre postMessage, propagación de cambios a todas las pestañas y arranque en frío.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 20, 'Por qué sincronizar es difícil', 'particiones y orden', 'El teorema CAP aplicado a tu aplicación, qué es de verdad una partición de red, y por qué el orden de los eventos es el problema central y no un detalle.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 21, 'Relojes I', 'el tiempo no existe', 'Por qué la hora del sistema es inservible para ordenar eventos distribuidos: deriva, ajustes, saltos. La relación de precedencia causal y los relojes de Lamport.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 22, 'Relojes II', 'vectores y relojes híbridos', 'Vector clocks y version vectors para detectar concurrencia real, su coste en espacio, y los relojes lógicos híbridos que juntan lo mejor de ambos mundos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 23, 'Detectar conflictos', 'y por qué LWW pierde datos', 'Qué es exactamente un conflicto, por qué "gana la última escritura" es la respuesta más común y la peor, y qué datos desaparecen sin que nadie se entere.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 24, 'OT frente a CRDT', 'las dos escuelas', 'La transformación operacional que hizo posible Google Docs y los tipos replicados sin conflicto. De dónde viene cada una, qué exige y dónde vive hoy cada enfoque.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 25, 'CRDT I', 'el teorema', 'La estructura algebraica que hay debajo: semirretículo de unión, conmutatividad, asociatividad e idempotencia. Por qué esas tres propiedades bastan para garantizar convergencia.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 26, 'CRDT II', 'estado, operaciones y deltas', 'Las dos familias, basada en estado y basada en operaciones, qué exige la red a cada una, y los CRDT delta que resolvieron el problema de enviar el estado entero.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 27, 'Contadores', 'el CRDT más simple', 'G-Counter y PN-Counter: el punto de partida para entender la mecánica. Por qué un contador distribuido no es un número y qué implica eso.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 28, 'Conjuntos', 'y el precio de borrar', 'G-Set, 2P-Set y OR-Set. El problema del borrado en un sistema sin autoridad central, las lápidas que deja detrás y por qué añadir es fácil y quitar no.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 29, 'Registros', 'un solo valor, varios dueños', 'LWW-Register y MV-Register: guardar un valor cuando dos personas lo escriben a la vez. Resolver por reloj o exponer el conflicto al usuario.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 30, 'Mapas y JSON', 'componer estructuras', 'Componer CRDT dentro de CRDT para representar documentos anidados, el problema de la eliminación de claves y el modelo JSON que usan las librerías reales.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 31, 'Secuencias I', 'el problema del orden', 'Por qué una lista es el caso difícil: hace falta poder crear un identificador estrictamente entre otros dos, infinitas veces, sin coordinación.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 32, 'Secuencias II', 'RGA, Logoot y Treedoc', 'Los algoritmos clásicos de lista replicada, sus estructuras internas y el compromiso que hace cada uno entre tamaño del identificador y coste de inserción.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 33, 'La intercalación', 'el fallo que nadie vio', 'El artículo de 2019 que destapó que casi todos los algoritmos entrelazan el texto de dos personas que escriben a la vez en el mismo punto. Por qué pasó desapercibido décadas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 34, 'Fugue', 'no intercalación maximal', 'El algoritmo que definió y resolvió la propiedad de no intercalación maximal, cómo lo consigue y por qué su formulación resultó ser más fácil de optimizar que las anteriores.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 35, 'Eg-walker', 'guardar operaciones, no metadatos', 'El enfoque que registra las operaciones originales en vez de la metadata del CRDT: un orden de magnitud menos de memoria y cargas de documento drásticamente más rápidas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 36, 'Árboles y movimiento', 'el problema del ciclo', 'Mover un nodo dentro de un árbol replicado puede crear un ciclo cuando dos personas lo hacen a la vez. Las estrategias para impedirlo y el coste de cada una.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 37, 'Construir un OR-Set', 'desde cero', 'Implementar un conjunto replicado paso a paso, con su prueba de convergencia y sus lápidas, para tocar con las manos lo que las lecciones anteriores describen.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 38, 'Construir una secuencia', 'RGA paso a paso', 'Implementar una lista replicada completa: identificadores, inserción, borrado, recorrido y la función de mezcla. El ejercicio que fija todo lo demás.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 39, 'Probar la convergencia', 'fuzzing y propiedades', 'Cómo se demuestra que tu implementación converge: pruebas basadas en propiedades, generación de historias concurrentes, simulación de particiones y reducción de casos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 40, 'Yjs', 'el estándar de facto', 'El modelo de documento, los tipos compartidos, el sistema de awareness para los cursores ajenos y los proveedores de transporte. Por qué domina el mercado de editores.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 41, 'Automerge', 'documentos e historia', 'El modelo de documento con historia completa, el formato de almacenamiento columnar de la versión 3 y las capacidades de viaje en el tiempo que eso habilita.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 42, 'Loro', 'texto rico y árboles', 'La apuesta escrita en Rust: texto enriquecido, árboles con movimiento y el algoritmo de recorrido del grafo de eventos. Qué gana y qué le falta de ecosistema.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 43, 'Elegir CRDT', 'la comparación honesta', 'Tamaño en disco, memoria en caliente, velocidad de carga, madurez del ecosistema y forma de los datos. Un criterio de elección, y los casos donde ninguno es la respuesta.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 44, 'El historial infinito', 'compactar sin romper', 'Un CRDT que guarda todo crece para siempre. Lápidas, compactación, instantáneas y la pregunta incómoda de qué historia puedes tirar sin romper a quien lleva meses desconectado.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 45, 'Direccionar por contenido I', 'el hash como identidad', 'La idea que cambia el modelo: el nombre de un dato es su hash. Inmutabilidad, deduplicación gratuita y verificación de integridad sin confiar en quien te lo envía.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 46, 'Direccionar por contenido II', 'Merkle DAG y CID', 'Grafos acíclicos dirigidos de Merkle, el troceado de ficheros grandes, los identificadores de contenido y el modelo de datos enlazados que usan los sistemas distribuidos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 47, 'Git como CAS', 'el ejemplo que ya usas', 'Git es un almacén direccionado por contenido con una interfaz de control de versiones encima. Objetos, árboles, commits y packfiles: lo que se aprende leyéndolo así.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 48, 'Funciones de hash', 'SHA-256 frente a BLAKE3', 'Qué se le pide a un hash en este contexto, por qué la velocidad y el paralelismo importan tanto como la resistencia a colisiones, y los árboles de hash verificables por trozos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 49, 'Reconciliación eficiente', 'saber qué falta sin mandarlo todo', 'El problema de averiguar la diferencia entre dos réplicas sin transmitirlas enteras: version vectors, filtros de Bloom y reconciliación de conjuntos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 50, 'P2P I', 'WebRTC y su peso', 'La pila que el navegador te da para conectar dos clientes: ICE, STUN, TURN, DTLS y SCTP. Por qué se diseñó para vídeo y qué cuesta usarla para sincronizar datos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 51, 'P2P II', 'libp2p, iroh y QUIC', 'Las alternativas modernas: la pila modular de libp2p, el enfoque de iroh sobre QUIC con claves como direcciones, y las tasas reales de éxito al perforar NAT.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 52, 'Motores de sync I', 'la taxonomía', 'El panorama de 2026 ordenado: autoridad en el servidor frente a convergencia por CRDT, sincronización de tablas frente a sincronización de documentos, y qué implica cada eje.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 53, 'Motores de sync II', 'los que existen', 'Zero, ElectricSQL, PowerSync, Jazz, LiveStore y compañía: cómo funciona cada uno por dentro, qué base de datos exige y para qué tipo de aplicación está pensado.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 54, 'Identidad sin servidor', 'DID y delegación', 'Quién eres cuando no hay servidor de sesiones: identificadores descentralizados, cadenas de certificados con enlace tardío y autorización delegada que funciona sin conexión.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 55, 'Cifrado extremo a extremo', 'sobre datos que convergen', 'El choque entre cifrar y sincronizar: qué puede ver el servidor, la gestión de claves entre dispositivos, los protocolos de mensajería en grupo y el control de acceso local-first.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 56, 'Migrar el esquema', 'datos que no controlas', 'El problema más difícil y el peor documentado: cambiar la forma de los datos cuando viven en dispositivos ajenos que llevan meses sin abrirse. Compatibilidad en las dos direcciones.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 57, 'Casos de estudio', 'qué hacen los que lo hacen', 'Cómo resolvieron esto en productos reales de escritorio y web: qué sincronizan, qué no, dónde ponen la autoridad y qué compromisos aceptaron a cambio.', NULL, NULL, NULL);
INSERT INTO level VALUES ('local-first', 58, 'Síntesis', 'síntesis y futuro', 'El modelo mental completo, el árbol de decisiones para elegir arquitectura, lo que sigue sin estar resuelto y hacia dónde va el campo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 0, 'Ontología', 'El mapa de Lua', 'La visión aérea: un lenguaje diminuto construido sobre tablas y closures, su máquina virtual de registros, la API C que lo hace embebible, y dónde vive hoy.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 1, 'El lenguaje', 'minimalismo como doctrina', 'De dónde sale Lua, la obsesión por el tamaño y la portabilidad, y por qué acabó dentro de juegos, de nginx, de Redis y de tu editor.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 2, 'Valores y tipos', 'ocho tipos y ya', 'Los tipos de Lua, la ausencia de declaraciones, `nil` frente a `false`, la verdad en Lua, y la diferencia entre valor e identidad.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 3, 'Números', 'enteros y flotantes', 'La división de números desde 5.3: subtipo entero y flotante, aritmética, división entera, conversiones implícitas y desbordamiento.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 4, 'Strings', 'inmutables e internadas', 'Las cadenas por dentro: inmutabilidad, internamiento de cadenas cortas, escapes, cadenas largas, y las cadenas externas de 5.5.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 5, 'Tablas I', 'el único tipo compuesto', 'La tabla como array, diccionario, objeto, módulo y espacio de nombres a la vez; constructores, claves, y el idioma de la tabla vacía.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 6, 'Tablas II', 'por dentro', 'La representación real: parte array y parte hash, el rehash y su coste, los arrays compactos de 5.5, y por qué el operador de longitud es traicionero.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 7, 'Funciones', 'valores de primera clase', 'Funciones como valores, retornos múltiples y sus reglas de ajuste, `...` y los varargs, y las tablas de varargs con nombre de 5.5.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 8, 'Closures y upvalues', 'el mecanismo real', 'Qué captura exactamente un closure: upvalues abiertos y cerrados, closures que comparten estado, y por qué esto define el estilo de Lua.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 9, 'Ámbito y globales', '_ENV lo explica todo', 'Locales frente a globales, el coste de un global, `_ENV` como upvalue implícito, entornos personalizados, y las declaraciones de globales de 5.5.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 10, 'Metatablas I', 'cambiar el comportamiento', 'El mecanismo que hace flexible a Lua: metatablas y metamétodos, `__index` con tabla y con función, `__newindex`, y las tablas de solo lectura.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 11, 'Metatablas II', 'el catálogo completo', 'Operadores aritméticos y de comparación, `__call`, `__tostring`, `__len`, `__gc`, y las variables to-be-closed con `__close`.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 12, 'Objetos en Lua', 'prototipos con metatablas', 'La orientación a objetos que no viene de fábrica: el idioma de la clase, `self` y los dos puntos, herencia, y las alternativas sin metatablas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 13, 'Módulos', 'require por dentro', 'Cómo carga Lua un módulo: `package.path` y `package.cpath`, los searchers, el caché de `package.loaded`, y escribir un módulo bien.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 14, 'Errores', 'pcall y nada más', 'El modelo de errores sin excepciones: `error` y sus niveles, `pcall` y `xpcall`, tracebacks, y el idioma de devolver `nil` con un mensaje.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 15, 'Corrutinas I', 'el modelo asimétrico', 'Corrutinas de verdad: `create`, `resume`, `yield` y el paso de valores en ambos sentidos; su estado, y en qué se diferencian de los hilos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 16, 'Corrutinas II', 'construir sobre ellas', 'Lo que se puede edificar encima: generadores, productores y consumidores, y cómo se implementa async sobre corrutinas en bibliotecas reales.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 17, 'Iteradores', 'el protocolo del for', 'El `for` genérico por dentro: la tripleta de función, estado y control; iteradores con y sin estado, y escribir los tuyos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 18, 'La biblioteca estándar', 'pequeña a propósito', 'Todo lo que trae Lua: `string`, `table`, `math`, `os`, `io`, `utf8`; qué falta deliberadamente y por qué no hay batteries included.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 19, 'Patrones', 'no son expresiones regulares', 'El lenguaje de patrones propio de Lua: clases, cuantificadores, capturas, anclas, `gsub` y `gmatch`, y sus límites frente a una regex.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 20, 'Metaprogramación', 'código que hace código', '`load` y la compilación en tiempo de ejecución, funciones como datos, generar Lua desde Lua, y los riesgos de hacerlo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 21, 'El recolector', 'incremental y generacional', 'La gestión de memoria: marcado y barrido incremental, el modo generacional, los cambios de 5.5, tablas débiles y finalizadores.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 22, 'La máquina virtual', 'bytecode de registros', 'La VM por dentro: registros en vez de pila, el formato de instrucción, `luac` y leer un volcado de bytecode de una función real.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 23, 'La pila de la API C', 'la disciplina del índice', 'El modelo que gobierna toda la API: una pila de valores, índices positivos y negativos, pseudoíndices, y las reglas que no puedes romper.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 24, 'La API C I', 'C llama a Lua', 'Crear un estado, cargar y ejecutar código, pasar y recoger valores, llamar funciones de Lua desde C, y manejar errores con longjmp.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 25, 'La API C II', 'Lua llama a C', 'Escribir funciones y módulos en C, userdata ligero y completo, metatablas desde C, y el registro de tipos propios.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 26, 'Embeber Lua', 'el lenguaje como biblioteca', 'Integrar Lua en una aplicación: estados y aislamiento, sandboxing real, límites de memoria y de instrucciones, y el patrón del motor de juego.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 27, 'LuaJIT', 'el otro Lua', 'Por qué medio mundo sigue en LuaJIT: compilación por trazas, la FFI que cambia las reglas, el estancamiento en 5.1, y cuándo elegirlo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 28, 'Rendimiento', 'dónde asigna Lua', 'Qué cuesta de verdad: creación de tablas y closures, concatenación de cadenas, locales frente a globales, y medir antes de creer.', NULL, NULL, NULL);
INSERT INTO level VALUES ('lua', 29, 'Síntesis', 'síntesis y la fuente', 'El modelo mental completo, leer el código fuente de Lua (que se puede leer entero), la comunidad y los dialectos, y dónde vive Lua hoy.', NULL, NULL, NULL);
INSERT INTO level VALUES ('maquinas', 0, 'Ontología', 'El mapa de las máquinas', 'La visión aérea: autómatas, statecharts de Harel, XState y el actor model; por qué modelar el estado como una máquina elimina lo imposible.', NULL, NULL, NULL);
INSERT INTO level VALUES ('maquinas', 1, 'Máquinas finitas', 'estados y transiciones', 'La FSM: un conjunto finito de estados, eventos que disparan transiciones, y por qué modelar así elimina estados imposibles.', NULL, NULL, NULL);
INSERT INTO level VALUES ('maquinas', 2, 'Statecharts', 'jerarquía y paralelismo', 'Los statecharts de Harel: estados jerárquicos, regiones paralelas, historia, y cómo domestican la explosión combinatoria.', NULL, NULL, NULL);
INSERT INTO level VALUES ('maquinas', 3, 'XState: el modelo', 'createMachine', 'XState v5: definir una máquina con estados y transiciones; el modelo de configuración y la ejecución determinista.', NULL, NULL, NULL);
INSERT INTO level VALUES ('maquinas', 4, 'XState: context y lógica', 'guards y actions', 'El estado extendido (context), guards, actions de entrada/salida, y assign para actualizar el context.', NULL, NULL, NULL);
INSERT INTO level VALUES ('maquinas', 5, 'XState: el actor model', 'actores y mensajes', 'En XState v5 el actor es la unidad central: entidades vivas que se comunican por mensajes asíncronos; spawn e invoke.', NULL, NULL, NULL);
INSERT INTO level VALUES ('maquinas', 6, 'XState: efectos', 'invoke y promesas', 'Invocar promesas, observables, callbacks y otras máquinas como actores; su ciclo de vida, resultados y errores.', NULL, NULL, NULL);
INSERT INTO level VALUES ('maquinas', 7, 'Máquinas en la UI', 'React, Vue, Solid', 'Conectar una máquina a la UI con useMachine/useActor; renderizar según el estado y enviar eventos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('maquinas', 8, 'Cuándo una máquina', 'y cuándo no', 'El criterio: dónde brillan las máquinas de estado y dónde son sobreingeniería.', NULL, NULL, NULL);
INSERT INTO level VALUES ('maquinas', 9, 'Teoría de autómatas', 'la base formal', 'La base matemática: autómatas finitos deterministas y no deterministas, lenguajes regulares, y qué puede y no puede expresar una FSM.', NULL, NULL, NULL);
INSERT INTO level VALUES ('maquinas', 10, 'SCXML y el estándar', 'la especificación', 'SCXML: el estándar W3C de statecharts que XState sigue; la semántica formal de las transiciones y por qué importa.', NULL, NULL, NULL);
INSERT INTO level VALUES ('maquinas', 11, 'XState v5: setup y tipos', 'type-safety total', 'La API `setup` de XState v5: tipar context, eventos, actores y acciones; inferencia y errores en tiempo de compilación.', NULL, NULL, NULL);
INSERT INTO level VALUES ('maquinas', 12, 'Jerarquía en XState', 'estados compuestos', 'Modelar estados anidados y paralelos en XState: submáquinas, regiones ortogonales, y las transiciones que cruzan niveles.', NULL, NULL, NULL);
INSERT INTO level VALUES ('maquinas', 13, 'Historia y finales', 'recordar y terminar', 'Estados de historia (shallow y deep), estados finales, `onDone` y el output de una máquina que termina.', NULL, NULL, NULL);
INSERT INTO level VALUES ('maquinas', 14, 'Testing de máquinas', 'model-based testing', 'Testear una máquina: transiciones puras, recorridos exhaustivos, y el model-based testing que genera casos desde el modelo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('maquinas', 15, 'Visualizar', 'Stately Studio', 'El diagrama como documentación viva: Stately Studio, el inspector, y diseñar la máquina visualmente antes de codificarla.', NULL, NULL, NULL);
INSERT INTO level VALUES ('maquinas', 16, 'Máquinas y datos', 'combinar con el servidor', 'Coordinar una máquina con el estado del servidor: invocar fetches, cachear, y no duplicar lo que ya gestiona TanStack Query.', NULL, NULL, NULL);
INSERT INTO level VALUES ('maquinas', 17, 'Máquinas en el backend', 'procesos y workflows', 'Statecharts fuera de la UI: modelar procesos de negocio, workflows durables, y máquinas que viven en el servidor.', NULL, NULL, NULL);
INSERT INTO level VALUES ('maquinas', 18, 'Patrón: wizards', 'flujos de varios pasos', 'El caso canónico: un asistente de varios pasos con validación, navegación hacia atrás, y estados de envío.', NULL, NULL, NULL);
INSERT INTO level VALUES ('maquinas', 19, 'Patrón: media', 'reproductores y carga', 'Modelar un reproductor (idle, cargando, reproduciendo, pausado, error) y cualquier recurso con ciclo de vida complejo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('maquinas', 20, 'Patrón: auth', 'sesiones y permisos', 'La máquina de autenticación: anónimo, autenticando, autenticado, refrescando, expirado; el flujo completo sin booleanos sueltos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('maquinas', 21, 'Actores distribuidos', 'más allá de una máquina', 'Sistemas de actores: jerarquías, supervisión, y la herencia de Erlang/Akka en el modelo de XState.', NULL, NULL, NULL);
INSERT INTO level VALUES ('maquinas', 22, 'Alternativas a XState', 'Robot, Zag, a mano', 'Otras librerías (Robot, Zag.js) y la FSM escrita a mano; cuándo no necesitas todo el peso de XState.', NULL, NULL, NULL);
INSERT INTO level VALUES ('maquinas', 23, 'Máquinas en otros lenguajes', 'Swift, Kotlin, Rust', 'El patrón fuera de JavaScript: enums con estado asociado en Swift y Rust, sealed classes en Kotlin, y el type-state pattern.', NULL, NULL, NULL);
INSERT INTO level VALUES ('maquinas', 24, 'Rendimiento y escala', 'máquinas grandes', 'Cuando la máquina crece: dividir en submáquinas, actores independientes, y el coste real de la interpretación.', NULL, NULL, NULL);
INSERT INTO level VALUES ('maquinas', 25, 'Síntesis', 'pensar en máquinas', 'La síntesis: modelar cualquier dominio como estados y transiciones, decidir cuándo aplicarlo, y el futuro de los statecharts.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 0, 'Ontología', 'el mapa de lo discreto', 'La visión aérea: el lenguaje (conjuntos, lógica, relaciones), la demostración, el conteo, las recurrencias y los grafos; y por qué esta es la matemática que un programador usa a diario sin llamarla por su nombre.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 1, 'Proposiciones', 'el álgebra de la verdad', 'Conectivas, tablas de verdad, equivalencias y formas normales, tratadas como herramienta: la condición de un `if` es una fórmula, y simplificarla es álgebra.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 2, 'Cuantificadores', 'para todo y existe', 'Predicados, dominio, el orden de los cuantificadores y su negación; por qué «todo elemento cumple» y «existe uno que cumple» no se intercambian impunemente.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 3, 'Conjuntos', 'pertenencia, igualdad y vacío', 'El conjunto como colección sin orden ni repetición: extensión y comprensión, pertenencia frente a inclusión, el vacío, y por qué un `Set` no es una lista sin duplicados.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 4, 'Operaciones de conjuntos', 'unión, intersección, diferencia', 'El álgebra de conjuntos y su parentesco con la lógica: De Morgan en las dos caras, el complemento y el universo, y las identidades que hay detrás de optimizar una consulta.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 5, 'Potencia y producto', 'subconjuntos y pares', 'El conjunto potencia con su 2 elevado a n y el producto cartesiano con su n por m: las dos operaciones que hacen crecer el espacio y explican de dónde sale la explosión combinatoria.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 6, 'Qué es demostrar', 'directa y contraposición', 'La demostración como argumento que convence a un escéptico: la forma directa, la contraposición, y la distancia entre comprobar casos y demostrar.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 7, 'Absurdo y contraejemplo', 'refutar y reducir', 'La reducción al absurdo con la raíz de dos y la infinitud de los primos, y el contraejemplo como la única refutación que necesita un «para todo».', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 8, 'Inducción', 'el principio y el esqueleto', 'Base, hipótesis y paso: la estructura de toda inducción, por qué es legítima y no una petición de principio, y su parentesco directo con la recursión que ya escribes.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 9, 'Inducción fuerte y estructural', 'la del programador', 'La inducción fuerte cuando el paso necesita todos los anteriores, y la estructural sobre árboles, listas y gramáticas: demostrar sobre tipos de datos recursivos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 10, 'Invariantes', 'la demostración que corre', 'El invariante de bucle como inducción aplicada a la ejecución: inicialización, conservación y terminación, más la función de cota que garantiza que el bucle acaba.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 11, 'Relaciones', 'el subconjunto del producto', 'Una relación como conjunto de pares: dominio y rango, sus tres caras —tabla, matriz booleana y grafo dirigido—, y la composición.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 12, 'Propiedades y clausuras', 'reflexiva, simétrica, transitiva', 'Las propiedades que clasifican una relación y la clausura como la menor extensión que las cumple: la transitiva es Warshall, y es el «alcanzable desde» de tu grafo de dependencias.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 13, 'Equivalencia', 'clases y particiones', 'La relación de equivalencia y el teorema que la convierte en partición; clases, representantes y conjunto cociente: por qué `equals` y `hashCode` viven juntos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 14, 'Órdenes parciales', 'el diagrama de Hasse', 'Orden parcial frente a total, maximales y máximos, el diagrama de Hasse, y la comparabilidad que falta: dos versiones concurrentes no son «una antes que la otra».', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 15, 'Retículos', 'ínfimo, supremo y la unión', 'Cotas, supremo e ínfimo, retículo y semirretículo; las tres propiedades —conmutativa, asociativa, idempotente— que hacen converger un CRDT.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 16, 'Funciones', 'inyectiva, sobreyectiva, biyectiva', 'La función como relación con una salida por entrada: imagen, preimagen, composición e inversa, y por qué el hash no es inyectivo y eso tiene consecuencias.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 17, 'Cardinalidad', 'contar lo infinito', 'La biyección como criterio de igual tamaño, los conjuntos numerables, la diagonal de Cantor, y el argumento de conteo que demuestra que casi ninguna función es computable.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 18, 'Los principios del conteo', 'suma, producto y biyección', 'Las tres reglas que resuelven casi todo: partir en casos disjuntos, multiplicar decisiones independientes, y contar otra cosa que esté en biyección con la que te importa.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 19, 'Permutaciones y combinaciones', 'importa el orden o no', 'Variaciones, permutaciones y combinaciones con las dos preguntas que las separan —importa el orden, se puede repetir—, y el factorial como fábrica de números enormes.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 20, 'El binomio', 'Pascal y sus identidades', 'El coeficiente binomial, el triángulo de Pascal como recurrencia, el teorema del binomio, y las identidades demostradas contando lo mismo de dos maneras.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 21, 'Inclusión-exclusión', 'quitar lo contado dos veces', 'El principio general, los desarreglos como caso célebre, y la aplicación diaria: el tamaño de una unión de conjuntos que se solapan.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 22, 'El palomar', 'lo inevitable por conteo', 'El principio del palomar y su forma generalizada: colisiones de hash garantizadas, la compresión universal sin pérdida que no puede existir, y los subconjuntos que siempre aparecen.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 23, 'Repetición y multiconjuntos', 'barras y estrellas', 'Combinaciones con repetición, permutaciones con elementos repetidos y el reparto en cajas: contar cuando los objetos o las urnas dejan de ser distinguibles.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 24, 'Recurrencias', 'definir por recursión', 'Definir una sucesión por su relación con los términos anteriores: Fibonacci, Hanoi y el número real de llamadas de tu función recursiva.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 25, 'Resolver recurrencias', 'lineales y homogéneas', 'La ecuación característica, el caso de raíces repetidas y la parte no homogénea: pasar de la recurrencia a la fórmula cerrada.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 26, 'Divide y vencerás', 'el teorema maestro', 'Las recurrencias que salen de partir el problema, los tres casos del teorema maestro, y su lectura honesta: dónde está el trabajo, en la partición o en las hojas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 27, 'Crecimiento', 'O, Omega y Theta', 'El orden de magnitud como relación entre funciones, la jerarquía habitual, y por qué la asintótica afirma algo sobre el límite y no sobre tu portátil.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 28, 'Grafos', 'el vocabulario', 'Vértices y aristas, dirigido o no, grado y el lema del apretón de manos, caminos y ciclos, subgrafos e isomorfismo: el diccionario mínimo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 29, 'Representar un grafo', 'matriz o listas', 'Matriz de adyacencia frente a listas de adyacencia: el compromiso entre memoria y consulta, la densidad como criterio, y las potencias de la matriz como conteo de caminos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 30, 'Recorridos', 'BFS y DFS', 'Los dos recorridos como hechos estructurales: el árbol que generan, la clasificación de aristas, y qué garantiza cada uno —BFS reparte distancias, DFS reparte tiempos—.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 31, 'Conectividad', 'componentes y cortes', 'Componentes conexas y fuertemente conexas, puntos de articulación y puentes: los vértices y las aristas cuya caída parte la red en dos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 32, 'Árboles', 'las caracterizaciones equivalentes', 'Seis definiciones que resultan ser la misma, el árbol de expansión y su versión mínima, y el conteo de árboles etiquetados.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 33, 'DAG', 'el orden topológico', 'El grafo dirigido acíclico como forma de todo sistema de dependencias: el orden topológico, su no unicidad, el ciclo como error, y el camino crítico de un build.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 34, 'Euler y Hamilton', 'gemelos y opuestos', 'Recorrer todas las aristas frente a recorrer todos los vértices: la caracterización local de Euler y el abismo de complejidad que separa los dos problemas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 35, 'Coloreado', 'el número cromático', 'Colorear vértices sin conflicto: cotas, grafos bipartitos, el voraz y su dependencia del orden, y la asignación de registros como coloreado de un grafo de interferencia.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 36, 'Emparejamientos', 'Hall y lo bipartito', 'El emparejamiento máximo, el teorema de Hall, los caminos aumentantes y el matrimonio estable: asignar sin conflictos y demostrar que se puede.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 37, 'Grafos planos', 'la fórmula de Euler', 'Dibujar sin cruces: vértices menos aristas más caras igual a dos, sus consecuencias sobre la densidad, los dos grafos prohibidos, y el layout de un diagrama como problema de planaridad.', NULL, NULL, NULL);
INSERT INTO level VALUES ('discrete-math', 38, 'Síntesis', 'la matemática que ya usabas', 'El mapa completo: reconocer la estructura discreta escondida en un problema de programación, elegir la herramienta, y el puente hacia algoritmos, complejidad y teoría de números.', NULL, NULL, NULL);
INSERT INTO level VALUES ('mvi', 0,'Ontología', 'El mapa de MVI', 'La visión aérea: Model-View-Intent en el mundo Kotlin/Android, Orbit, coroutines y Compose; el flujo unidireccional nativo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('mvi', 1, 'MVI', 'Model-View-Intent', 'Model-View-Intent: la intención del usuario como entrada, un modelo inmutable como salida, y el ciclo unidireccional.', NULL, NULL, NULL);
INSERT INTO level VALUES ('mvi', 2, 'Orbit MVI', 'container y side effects', 'Orbit (Kotlin): el container que reduce intents a estado, los side effects de una sola vez, y su ergonomía sobre coroutines.', NULL, NULL, NULL);
INSERT INTO level VALUES ('mvi', 3, 'Kotlin para MVI', 'data y sealed classes', 'Las piezas del lenguaje: data classes para el estado inmutable, sealed classes/interfaces para intents y efectos, y `when` exhaustivo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('mvi', 4, 'Coroutines', 'concurrencia estructurada', 'Coroutines: suspend, scopes, structured concurrency, y por qué el ciclo de vida de una corrutina encaja con el de una pantalla.', NULL, NULL, NULL);
INSERT INTO level VALUES ('mvi', 5, 'Flow y StateFlow', 'streams en Kotlin', 'Flow: streams fríos y calientes, `StateFlow` como estado observable, `SharedFlow` para eventos, y los operadores clave.', NULL, NULL, NULL);
INSERT INTO level VALUES ('mvi', 6, 'El ViewModel', 'el hogar del estado', 'El ViewModel de Android: sobrevivir a cambios de configuración, `viewModelScope`, y por qué es el lugar natural del container.', NULL, NULL, NULL);
INSERT INTO level VALUES ('mvi', 7, 'Estado en Compose', 'recomposición', 'Jetpack Compose: `collectAsStateWithLifecycle`, recomposición, y renderizar la UI como función del estado.', NULL, NULL, NULL);
INSERT INTO level VALUES ('mvi', 8, 'Estabilidad y skipping', 'rendimiento en Compose', 'Por qué Compose recompone de más: estabilidad de tipos, clases inmutables, y cómo el estado inmutable de MVI ayuda.', NULL, NULL, NULL);
INSERT INTO level VALUES ('mvi', 9, 'Intents y reducers', 'la transición', 'Modelar los intents del usuario y reducirlos a estado: funciones puras, validación, y el orden de las transiciones.', NULL, NULL, NULL);
INSERT INTO level VALUES ('mvi', 10, 'Side effects', 'eventos de una sola vez', 'Lo que no es estado: navegar, mostrar un snackbar, vibrar; por qué mezclarlos con el estado provoca bugs al rotar la pantalla.', NULL, NULL, NULL);
INSERT INTO level VALUES ('mvi', 11, 'Orbit: el container', 'la API a fondo', 'El container de Orbit: `intent`, `reduce`, `postSideEffect`, el `stateFlow` y el `sideEffectFlow`; su modelo de concurrencia.', NULL, NULL, NULL);
INSERT INTO level VALUES ('mvi', 12, 'Orbit: testing', 'assertions del flujo', 'Testear con orbit-test: afirmar la secuencia de estados y efectos, y controlar el tiempo y las dependencias.', NULL, NULL, NULL);
INSERT INTO level VALUES ('mvi', 13, 'MVI a mano', 'sin librería', 'Implementar MVI con solo Kotlin: un `StateFlow` privado, una función `reduce`, y un `Channel` para los efectos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('mvi', 14, 'Navegación', 'estado y destinos', 'Navegación en Android moderno: Navigation Compose, la navegación como efecto o como estado, y el deep linking.', NULL, NULL, NULL);
INSERT INTO level VALUES ('mvi', 15, 'Capa de datos', 'repositorios y fuentes', 'Debajo del ViewModel: repositorios, fuentes locales (Room) y remotas, y exponer los datos como Flow.', NULL, NULL, NULL);
INSERT INTO level VALUES ('mvi', 16, 'Inyección de dependencias', 'Hilt y Koin', 'DI en Android: Hilt (compile-time) y Koin (runtime); inyectar el container y hacer testeable la capa de presentación.', NULL, NULL, NULL);
INSERT INTO level VALUES ('mvi', 17, 'Kotlin Multiplatform', 'compartir el estado', 'KMP: compartir la lógica MVI entre Android e iOS, exponerla a Swift, y qué se comparte y qué no.', NULL, NULL, NULL);
INSERT INTO level VALUES ('mvi', 18, 'Testing de presentación', 'la pirámide', 'Testear la capa de presentación: unit tests del reducer, tests del ViewModel con turbine, y tests de UI en Compose.', NULL, NULL, NULL);
INSERT INTO level VALUES ('mvi', 19, 'MVI vs MVVM vs MVP', 'la comparación', 'Las arquitecturas de Android comparadas: qué añade el flujo unidireccional estricto y qué cuesta en ceremonia.', NULL, NULL, NULL);
INSERT INTO level VALUES ('mvi', 20, 'Errores comunes', 'y cómo evitarlos', 'Los tropiezos típicos: estado gigante, efectos tratados como estado, fugas de scope, y recomposiciones descontroladas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('mvi', 21, 'Síntesis', 'MVI en la práctica', 'La síntesis: arquitectar una app Android completa con MVI, decidir librería o no, y el futuro del estado en Compose.', NULL, NULL, NULL);
INSERT INTO level VALUES ('neovim', 0, 'Fundamentos', 'Sin configurar nada', 'Qué es Neovim y por qué. La filosofía modal, el arsenal completo de movimientos, la "gramática" de operadores y complementos, el modo Insertar a fondo, leer la ayuda oficial, y qué trajo de verdad la 0.12. Siete lecciones sin configurar nada.', NULL, NULL, '0');
INSERT INTO level VALUES ('neovim', 1, 'El editor desnudo', 'Buffers, registros, macros y quickfix', 'El editor que ya tienes instalado, sin un solo plugin ni una línea de configuración: buffers y ventanas, registros y marcas, buscar y reemplazar, el comando global, macros, la quickfix, el plegado y el árbol de deshacer.', 'var(--teal)', '#94e2d5', NULL);
INSERT INTO level VALUES ('neovim', 2, 'Configuración desde cero', 'Config desde cero', 'Construye tu propia configuración en Lua desde un init.lua vacío. Opciones, keymaps, leader, el presupuesto de teclas y tu primer gestor de plugins.', NULL, NULL, NULL);
INSERT INTO level VALUES ('neovim', 3, 'LSP, completado y Treesitter', 'IDE completo', 'Convierte Neovim en un IDE: LSP nativo, autocompletado, Treesitter, Git, depuración y setups afinados para C, Rust, Swift y frontend.', NULL, NULL, NULL);
INSERT INTO level VALUES ('neovim', 4, 'Entorno', 'Alrededor del editor', 'Lo que rodea al editor: el picker para navegar buscando, la terminal integrada, la IA por capas y el flujo de trabajo completo.', 'var(--peach)', '#fab387', NULL);
INSERT INTO level VALUES ('neovim', 5, 'Distribuciones y LazyVim', '¿Construir o adoptar?', 'Distribuciones y LazyVim: cuándo usar una distro, LazyVim a fondo, personalizarlo sin romperlo y migrar con control total.', 'var(--yellow)', '#f9e2af', NULL);
INSERT INTO level VALUES ('neovim', 6, 'Práctica deliberada', 'Cómo entrenar lo aprendido', 'El dojo: práctica deliberada, drills de vim-golf, un recorrido de entrenamiento guiado y un plan de 30 días para consolidar todo lo aprendido.', 'var(--pink)', '#f5c2e7', NULL);
INSERT INTO level VALUES ('neovim', 7, 'Lua', 'el lenguaje del editor', 'Lua en el contexto de Neovim: tablas, metatablas, closures, módulos y el runtimepath; lo que de verdad necesitas para configurar y extender.', NULL, NULL, NULL);
INSERT INTO level VALUES ('neovim', 8, 'La API', 'vim.api, vim.fn, vim.opt', 'Las tres capas de la API: vim.api (nvim_*), vim.fn para las funciones de Vimscript, vim.opt para opciones, y cuándo usar cada una.', NULL, NULL, NULL);
INSERT INTO level VALUES ('neovim', 9, 'Autocomandos', 'reaccionar a eventos', 'El sistema de eventos: autocomandos desde Lua, grupos, patrones, eventos personalizados con User, y depurar por qué no dispara.', NULL, NULL, NULL);
INSERT INTO level VALUES ('neovim', 10, 'Buffers y ventanas', 'la API desde dentro', 'Manipular el editor por código: crear y modificar buffers, ventanas y pestañas, buffers scratch, y las opciones por ámbito.', NULL, NULL, NULL);
INSERT INTO level VALUES ('neovim', 11, 'Keymaps y comandos', 'extender la interfaz', 'Definir mapeos desde Lua con callbacks, comandos de usuario con argumentos y completado, y operadores propios con operatorfunc.', NULL, NULL, NULL);
INSERT INTO level VALUES ('neovim', 12, 'El event loop', 'libuv y vim.uv', 'El corazón asíncrono: libuv bajo Neovim, vim.uv, timers, vim.schedule y la regla de oro de no tocar la API desde el hilo del loop.', NULL, NULL, NULL);
INSERT INTO level VALUES ('neovim', 13, 'Procesos externos', 'jobs y terminal', 'Hablar con el sistema: vim.system, jobs asíncronos, leer stdout en streaming, el buffer de terminal y construir integraciones.', NULL, NULL, NULL);
INSERT INTO level VALUES ('neovim', 14, 'Extmarks', 'anotar el texto', 'El sistema de marcas extendidas: namespaces, virtual text, signos, resaltado por rango, y cómo lo usan los plugins modernos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('neovim', 15, 'Highlights', 'el sistema de color', 'Cómo colorea Neovim: grupos de resaltado, enlaces, treesitter frente a syntax, y escribir un esquema de color propio.', NULL, NULL, NULL);
INSERT INTO level VALUES ('neovim', 16, 'Treesitter: el árbol', 'parseo incremental', 'Qué es Treesitter: gramáticas, parseo incremental, el árbol sintáctico concreto, y por qué sustituyó a las expresiones regulares.', NULL, NULL, NULL);
INSERT INTO level VALUES ('neovim', 17, 'Treesitter: queries', 'capturas y predicados', 'El lenguaje de consultas: patrones, capturas, predicados y directivas; escribir tus propias queries y depurarlas con el playground.', NULL, NULL, NULL);
INSERT INTO level VALUES ('neovim', 18, 'Treesitter aplicado', 'text objects y más', 'Usar el árbol para trabajar: text objects sintácticos, navegación estructural, plegado, indentación y refactorizaciones.', NULL, NULL, NULL);
INSERT INTO level VALUES ('neovim', 19, 'El protocolo LSP', 'qué habla el servidor', 'LSP por dentro: JSON-RPC, el handshake de capacidades, las peticiones y notificaciones clave, y leer el tráfico real.', NULL, NULL, NULL);
INSERT INTO level VALUES ('neovim', 20, 'vim.lsp', 'el cliente por dentro', 'El cliente de Neovim: configurar servidores sin distribución, handlers propios, diagnósticos, y extender el comportamiento por defecto.', NULL, NULL, NULL);
INSERT INTO level VALUES ('neovim', 21, 'Tu primer plugin', 'de la idea al require', 'Escribir un plugin de verdad: la estructura de directorios, lua/ y plugin/, setup y configuración, y la carga perezosa.', NULL, NULL, NULL);
INSERT INTO level VALUES ('neovim', 22, 'Publicar un plugin', 'API, docs y versiones', 'Del código al ecosistema: diseñar la API pública, escribir documentación en formato help, versionar, y no romper a tus usuarios.', NULL, NULL, NULL);
INSERT INTO level VALUES ('neovim', 23, 'Testear plugins', 'busted y plenary', 'Calidad en un plugin: tests con plenary o busted, instancias headless de Neovim, y ejecutar la suite en CI.', NULL, NULL, NULL);
INSERT INTO level VALUES ('neovim', 24, 'Construir interfaz', 'ventanas flotantes y UI', 'La UI de un plugin: ventanas flotantes, bordes, popups, statusline y winbar propias, y las convenciones de una buena interfaz.', NULL, NULL, NULL);
INSERT INTO level VALUES ('neovim', 25, 'Rendimiento', 'un editor instantáneo', 'Que nada se note: medir el arranque, perfilar Lua, carga perezosa real, y las causas típicas de que Neovim se atasque.', NULL, NULL, NULL);
INSERT INTO level VALUES ('neovim', 26, 'Síntesis', 'síntesis y contribuir', 'La síntesis: el modelo mental completo de Neovim como plataforma, leer su código fuente, contribuir al core, y hacia dónde va el editor.', NULL, NULL, NULL);
INSERT INTO level VALUES ('reactividad-fina', 0, 'Ontología', 'El mapa de los motores de reactividad', 'Qué es un motor de reactividad, las familias que existen, y por qué todos resuelven el mismo problema distinto.', NULL, NULL, NULL);
INSERT INTO level VALUES ('reactividad-fina', 1, 'Grano fino y grano grueso', 'La distinción fundamental', 'Re-renderizar un componente frente a actualizar un nodo del DOM: las dos filosofías y su coste real.', NULL, NULL, NULL);
INSERT INTO level VALUES ('reactividad-fina', 2, 'El grafo reactivo', 'Nodos, aristas y dependencias', 'La estructura de datos que hay debajo: fuentes, computaciones, observadores, y cómo se descubren las dependencias.', NULL, NULL, NULL);
INSERT INTO level VALUES ('reactividad-fina', 3, 'Tracking automático', 'Cómo sabe de qué depende', 'El observador actual como variable global, la recolección durante la ejecución, y por qué las condicionales cambian el grafo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('reactividad-fina', 4, 'Push, pull y push-pull', 'Los tres modelos de propagación', 'Propagar el cambio hacia adelante, calcular bajo demanda, y el modelo híbrido que evita glitches y trabajo inútil.', NULL, NULL, NULL);
INSERT INTO level VALUES ('reactividad-fina', 5, 'Glitches y consistencia', 'El diamante y el estado imposible', 'El problema del rombo en el grafo, la consistencia glitch-free, el marcado sucio en dos fases y la topología.', NULL, NULL, NULL);
INSERT INTO level VALUES ('reactividad-fina', 6, 'Memoización', 'Cachés que se invalidan solas', 'Qué hace un memo por debajo, la igualdad como frontera de propagación, y el memo como corta-circuitos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('reactividad-fina', 7, 'El árbol de dueños', 'Ownership y disposal automático', 'El mecanismo que ninguna otra familia tiene igual: quién posee a quién, la limpieza en cascada, y las raíces.', NULL, NULL, NULL);
INSERT INTO level VALUES ('reactividad-fina', 8, 'Lotes y planificación', 'Batching y el momento de ejecutar', 'Agrupar cambios, la cola de efectos, síncrono frente a asíncrono, y el orden de ejecución garantizado.', NULL, NULL, NULL);
INSERT INTO level VALUES ('reactividad-fina', 9, 'Reactividad profunda', 'Proxies y el estado anidado', 'Hacer reactivo un objeto entero, el coste del proxy, la reactividad perezosa y la trampa de la desestructuración.', NULL, NULL, NULL);
INSERT INTO level VALUES ('reactividad-fina', 10, 'Los motores comparados', 'Solid, Vue, Angular, Svelte, Preact', 'Las decisiones de diseño de cada uno lado a lado: qué comparten, en qué divergen y qué paga cada elección.', NULL, NULL, NULL);
INSERT INTO level VALUES ('reactividad-fina', 11, 'Compilar la reactividad', 'Cuando el compilador hace el trabajo', 'Svelte y sus runes, el compilador de Solid, React Compiler: qué se puede mover a build time y qué no.', NULL, NULL, NULL);
INSERT INTO level VALUES ('reactividad-fina', 12, 'Síntesis', 'Síntesis de la reactividad fina', 'El diseño completo de un motor de reactividad desde cero, las decisiones y sus consecuencias, y hacia dónde va TC39.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 0, 'Ontología', 'El mapa del rendimiento web', 'Qué significa rápido, las tres fases (carga, interacción, estabilidad), y el mapa completo de causas y remedios.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 1, 'La percepción del tiempo', 'Qué siente el usuario', 'Los umbrales de percepción humana, por qué la métrica no es el sentimiento, y el rendimiento percibido.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 2, 'Core Web Vitals', 'LCP, INP y CLS', 'Qué mide cada una exactamente, los umbrales, por qué INP reemplazó a FID, y qué NO capturan.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 3, 'Campo y laboratorio', 'RUM frente a sintético', 'CrUX y los datos reales, Lighthouse y su simulación, por qué difieren, y cuál manda para tomar decisiones.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 4, 'Medir en producción', 'La librería web-vitals y los percentiles', 'Instrumentar el sitio, enviar con sendBeacon, por qué el p75 y no la media, y segmentar por dispositivo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 5, 'La red', 'Latencia, ancho de banda y el RTT', 'Por qué la latencia domina, el handshake, el DNS, y por qué duplicar el ancho de banda casi no ayuda.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 6, 'HTTP moderno', 'De 1.1 a 3 y QUIC', 'El head-of-line blocking en cada versión, la multiplexación, QUIC sobre UDP, y qué cambia en la práctica.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 7, 'Caché HTTP', 'Las cabeceras que importan', 'Cache-Control por dentro, immutable, stale-while-revalidate, ETag, y la estrategia de nombres con hash.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 8, 'Compresión', 'gzip, Brotli y Zstd', 'Qué comprime bien y qué no, los niveles y su coste, la compresión estática, y el estado de Zstd en la web.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 9, 'La ruta crítica', 'Qué bloquea el primer pintado', 'El CSS bloqueante, el JS bloqueante, defer y async, y el modelo mental de la ruta crítica de render.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 10, 'Prioridades de recursos', 'preload, preconnect, fetchpriority', 'Las pistas al navegador, cuándo ayudan y cuándo hacen daño, y la prioridad implícita de cada tipo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 11, 'Optimizar LCP', 'El elemento más grande', 'Identificarlo, el descubrimiento temprano, la imagen del hero, y las cuatro subpartes del LCP.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 12, 'Imágenes I', 'Formatos y compresión', 'AVIF, WebP y JPEG, la calidad perceptual, el elemento picture, y elegir formato por tipo de imagen.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 13, 'Imágenes II', 'Responsive, lazy y placeholders', 'srcset y sizes de verdad, loading lazy y sus trampas, decoding, y los placeholders que no causan CLS.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 14, 'Vídeo y media', 'El recurso más pesado', 'Los códecs y contenedores, el streaming adaptativo, preload metadata, y sustituir GIF por vídeo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 15, 'JavaScript I', 'El coste real de un byte de JS', 'Descarga, parseo, compilación y ejecución: por qué un KB de JS cuesta mucho más que un KB de imagen.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 16, 'JavaScript II', 'Presupuesto y análisis del bundle', 'Fijar un performance budget, analizar el bundle, encontrar la dependencia gorda y el coste de las polyfills.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 17, 'Code splitting', 'Cargar lo que hace falta', 'La división por ruta y por interacción, el import dinámico, el preload del chunk, y el patrón de isla.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 18, 'Tree shaking', 'Eliminar lo muerto', 'Por qué depende de ESM, sideEffects, qué lo rompe, y verificar que de verdad se eliminó.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 19, 'El hilo principal', 'Long tasks y bloqueo', 'Qué es una long task, el TBT, por qué bloquear 200ms arruina el INP, y cómo encontrarlas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 20, 'Ceder el hilo', 'yield, scheduler y las tareas', 'scheduler.yield y postTask, el patrón de trocear trabajo, isInputPending, y las prioridades de tarea.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 21, 'Optimizar INP', 'La interacción que responde', 'Las tres partes del INP, separar respuesta visual de trabajo pesado, y el patrón de doble rAF.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 22, 'Web Workers', 'Sacar el trabajo del hilo', 'Qué se puede mover, el coste de postMessage, los transferables, Comlink, y los casos donde no compensa.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 23, 'Optimizar CLS', 'El layout que no salta', 'Reservar espacio con aspect-ratio, las fuentes y su métrica, el contenido inyectado, y size-adjust.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 24, 'Fuentes y rendimiento', 'El texto que aparece rápido', 'La cadena de carga de una fuente, font-display, el preload, los descriptores de ajuste y la fuente del sistema.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 25, 'Renderizado I', 'El pipeline de píxeles', 'Style, layout, paint y composite, qué dispara cada etapa, y leer el waterfall de un frame.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 26, 'Renderizado II', 'Layout thrashing y el DOM', 'La lectura forzada del layout, el patrón leer-luego-escribir, las propiedades que fuerzan sincronía.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 27, 'Renderizado III', 'contain y content-visibility', 'Aislar subárboles del layout, renderizar solo lo visible, contain-intrinsic-size y el efecto real.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 28, 'Listas grandes', 'Virtualización y paginación', 'Por qué 10.000 nodos matan la página, la ventana virtual, el scroll infinito y sus problemas de a11y.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 29, 'Memoria', 'Fugas y presión', 'El heap en DevTools, los tres snapshots, los detached nodes, los listeners que nunca se van y measureUserAgentSpecificMemory.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 30, 'Estrategias de render', 'SSR, SSG, ISR y CSR', 'El coste de cada una en las métricas, el streaming, la hidratación como problema, y el árbol de decisión.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 31, 'Hidratación', 'El impuesto del SSR', 'Por qué hidratar es caro, la hidratación parcial y progresiva, la resumibilidad, y las islas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 32, 'El edge y la CDN', 'Acercar el byte al usuario', 'Qué se puede cachear en el borde, el cache key, la revalidación, y el cómputo en el edge.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 33, 'Service Workers', 'Control total de la red', 'El ciclo de vida, las estrategias de caché, el app shell, y el riesgo de un SW mal desplegado.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 34, 'Terceros', 'El código que no controlas', 'Medir el coste de cada script de terceros, el facade pattern, Partytown, y la negociación con marketing.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 35, 'Rendimiento en móvil', 'El dispositivo real de tus usuarios', 'El throttling de CPU y red, el thermal throttling, la memoria limitada, y probar en gama baja.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 36, 'Rendimiento en CI', 'Evitar la regresión', 'Lighthouse CI, los presupuestos que fallan el build, el bundle diff en el PR, y qué medir en cada commit.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 37, 'El caso de negocio', 'Convertir milisegundos en dinero', 'Los estudios que correlacionan velocidad y conversión, cómo medirlo en tu producto, y cómo presentarlo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rendimiento', 38, 'Síntesis', 'Síntesis del rendimiento web', 'El método completo de diagnóstico, el árbol de decisión por síntoma, la cultura de rendimiento en un equipo, y hacia dónde va el rendimiento web.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 0, 'Ontología', 'El mapa de Rust', 'La visión aérea: qué hace único a Rust, sus pilares (ownership, traits, seguridad) y el mapa mental del camino.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 1, 'Por qué Rust', 'seguridad sin GC, la mentalidad', 'Seguridad de memoria garantizada en compilación sin recolector de basura, y la mentalidad que exige.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 2, 'Setup y cargo', 'rustup, cargo, edición 2024', 'Instalar la toolchain, cargo, y la edición 2024 (Polonius, async closures).', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 3, 'Variables y tipos', 'let, mut, tipos escalares', 'Inmutabilidad por defecto, shadowing, tipos escalares y la inferencia de Rust.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 4, 'Control de flujo', 'if, loop, while, match', 'if como expresión, los bucles, y la primera mirada a match.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 5, 'Structs y métodos', 'modelar datos', 'Structs, impl, métodos, y la diferencia con las clases de otros lenguajes.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 6, 'Enums y pattern matching', 'el superpoder de Rust', 'Enums con datos, match exhaustivo, if let, y modelar estados imposibles de romper.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 7, 'Option y Result', 'sin null ni excepciones', 'Los tipos que eliminan el null y las excepciones: valores que pueden faltar o fallar, explícitos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 8, 'Ownership', 'move semantics', 'El corazón de Rust: cada valor tiene un dueño, y mover transfiere la propiedad. Sin copias ni GC.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 9, 'Borrowing', 'referencias y reglas', 'Prestar en vez de mover: referencias compartidas (&) y mutables (&mut), y la regla del prestador.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 10, 'Lifetimes', 'validez de las referencias', 'Cómo Rust demuestra que una referencia nunca sobrevive a lo que apunta. Anotaciones de lifetime.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 11, 'Strings y slices', 'String vs &str', 'El modelo de cadenas de Rust, los slices, y por qué hay dos tipos de string.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 12, 'Domar el borrow checker', 'pensar en ownership', 'Los errores clásicos del borrow checker, NLL, Polonius, y cómo reestructurar en vez de pelear.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 13, 'Traits', 'comportamiento compartido', 'Los traits definen capacidades (como interfaces), con implementaciones por defecto. La abstracción de Rust.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 14, 'Genéricos', 'código para cualquier tipo', 'Funciones y tipos genéricos con bounds de trait, monomorfización y abstracción de coste cero.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 15, 'Trait objects', 'dispatch dinámico', 'dyn Trait, dispatch estático vs dinámico, y cuándo usar cada uno.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 16, 'Traits del sistema', 'Clone, Copy, Debug, Default', 'Los traits derivables que todo tipo usa, PartialEq/Eq/Ord/Hash, y qué significa cada uno.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 17, 'Deref, Drop y operadores', 'traits que dan superpoderes', 'Sobrecargar operadores, Deref coercion, y Drop (el destructor determinista de Rust).', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 18, 'Associated types y GATs', 'el sistema de tipos avanzado', 'Tipos asociados, Generic Associated Types, y cómo expresan relaciones ricas entre tipos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 19, 'Colecciones', 'Vec, HashMap, BTreeMap', 'Las colecciones de la librería estándar, cuándo usar cada una y su rendimiento.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 20, 'Iteradores', 'la pereza y su poder', 'El trait Iterator, la evaluación perezosa, y map/filter/fold: transformar sin bucles.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 21, 'Closures', 'Fn, FnMut, FnOnce', 'Las funciones anónimas que capturan su entorno, sus tres traits, y move closures.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 22, 'Iteradores avanzados', 'adaptadores y colecciones', 'Adaptadores (zip, chain, flat_map), collect, y escribir tu propio iterador.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 23, 'Manejo de errores', 'Result, ?, panic', 'El operador ?, propagar errores, y cuándo panic vs Result.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 24, 'Errores propios', 'thiserror y anyhow', 'Diseñar tipos de error, el trait Error, y las crates thiserror (librerías) y anyhow (apps).', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 25, 'Smart pointers', 'Box, Rc, Arc', 'Punteros con semántica propia: Box (heap), Rc (contado), Arc (contado y thread-safe).', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 26, 'Interior mutability', 'Cell, RefCell', 'Mutar a través de una referencia compartida de forma controlada, y el borrow checking en runtime.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 27, 'Lifetimes avanzados', 'los casos difíciles', 'Lifetime bounds, elisión, HRTB, y los patrones que confunden al borrow checker.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 28, 'Pin y auto-referencias', 'estructuras que se apuntan a sí mismas', 'Por qué Rust prohíbe mover ciertos valores, Pin, y la base de los futures async.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 29, 'Concurrencia con threads', 'fearless concurrency', 'Crear hilos, mover datos entre ellos, y por qué Rust hace imposibles las data races.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 30, 'Send y Sync', 'la seguridad entre hilos', 'Los dos traits marcadores que el compilador usa para garantizar concurrencia segura.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 31, 'Estado compartido', 'Arc, Mutex, channels', 'Compartir datos entre hilos con Arc<Mutex>, y comunicar con canales (paso de mensajes).', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 32, 'async/await', 'fundamentos', 'La sintaxis async/await, qué es una función async, y por qué Rust no trae runtime.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 33, 'Futures y poll', 'el modelo de Rust', 'El trait Future, el modelo poll/wake, y cómo una función async es una máquina de estados.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 34, 'Tokio', 'el runtime', 'El runtime async de facto: el scheduler work-stealing, el I/O driver, tasks y spawn.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 35, 'async avanzado', 'streams, select, cancelación', 'Streams, select!, join!, la cancelación por drop, y las async closures de la edición 2024.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 36, 'Depurar async', 'tokio-console, tracing', 'Observar y depurar código async: tokio-console, tracing, y los deadlocks async.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 37, 'Unsafe', 'cuándo y por qué', 'Qué desbloquea unsafe, por qué existe, y la responsabilidad que implica.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 38, 'Punteros crudos', 'los cinco superpoderes', 'Raw pointers, dereferenciarlos, y las cinco cosas que solo unsafe permite.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 39, 'FFI con C', 'interoperar', 'Llamar C desde Rust y Rust desde C, extern, bindgen, y la ABI.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 40, 'Abstracciones seguras', 'envolver unsafe', 'El patrón clave: encapsular unsafe tras una API segura cuyas invariantes garantizas tú.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 41, 'no_std', 'Rust sin librería estándar', 'El atributo #![no_std], el crate core, y programar sin sistema operativo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 42, 'Embebido', 'microcontroladores', 'Rust en microcontroladores: embedded-hal, PACs, RTIC y Embassy (async embebido).', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 43, 'Allocators y memoria', 'a bajo nivel', 'GlobalAlloc, allocators a medida, y la gestión de memoria de bajo nivel.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 44, 'Macros declarativas', 'macro_rules!', 'Generar código con macro_rules!: patrones, repetición, y la higiene de macros.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 45, 'Macros procedurales', 'derive y attribute', 'Macros que manipulan el AST: derive, attribute y function-like, con syn y quote.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 46, 'Programación a nivel de tipos', 'el sistema de tipos como lenguaje', 'Typestate, phantom types, y usar el sistema de tipos para prevenir errores en compilación.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 47, 'Cargo a fondo', 'workspaces, features, perfiles', 'Workspaces, features condicionales, perfiles de build, y el ecosistema de crates.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 48, 'Testing', 'unit, integration, doc, property', 'Los tests integrados, doc tests, y el testing basado en propiedades (proptest).', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 49, 'Rendimiento', 'zero-cost, SIMD', 'Las abstracciones de coste cero, perfilar (samply), SIMD, y optimización guiada por datos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 50, 'Publicar y ecosistema', 'crates.io, docs.rs', 'Publicar un crate, documentar, semver, y las herramientas del ecosistema.', NULL, NULL, NULL);
INSERT INTO level VALUES ('rust', 51, 'Internals y el futuro', 'MIR, el compilador, el futuro', 'Cómo funciona el compilador de Rust (HIR, MIR, borrow checker), y hacia dónde va el lenguaje.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 0, 'Ontología', 'El mapa de Solid', 'La visión aérea de SolidJS: reactividad de grano fino, el grafo, componentes que corren una vez, stores, async y SolidStart. El mapa mental completo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 1, 'Por qué Solid', 'grano fino vs VDOM', 'La idea central: reactividad de grano fino sin virtual DOM ni re-render. Comparación honesta con React y por qué Solid es tan rápido.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 2, 'Setup y JSX de Solid', 'no es React', 'Crear un proyecto, el JSX de Solid (se compila a DOM real), y las diferencias sutiles pero críticas con el JSX de React.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 3, 'createSignal', 'el átomo reactivo', 'El primitivo fundamental: getter/setter, lectura reactiva vs no reactiva, y por qué un signal es una función.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 4, 'createEffect', 'reacciones a los signals', 'Efectos que se re-ejecutan cuando sus dependencias cambian: tracking automático, timing, y el primer render.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 5, 'createMemo', 'valores derivados', 'Memos: derivaciones cacheadas que solo recalculan cuando cambian sus fuentes; cuándo un memo y cuándo una función.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 6, 'El modelo de ejecución', 'el componente corre una vez', 'La diferencia mental clave: el cuerpo del componente se ejecuta UNA sola vez; la reactividad vive en el JSX y los efectos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 7, 'Props', 'mergeProps, splitProps', 'Las props son reactivas: por qué NO destructurarlas, mergeProps para defaults, splitProps para separar, y la reactividad que se pierde.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 8, 'children()', 'resolver hijos', 'El helper children(): resolver y memoizar los hijos, evitar re-crearlos, y manipular el árbol de forma segura.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 9, 'Eventos y binding', 'on:, delegación, refs', 'Manejo de eventos (delegados y nativos), binding de atributos y propiedades, classList, style, y el atributo ref.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 10, 'El grafo reactivo', 'observers y sources', 'Cómo funciona por dentro: nodos, observers y sources, propagación push/pull, y por qué no hay diffing.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 11, 'Ownership y cleanup', 'onCleanup, getOwner', 'El árbol de ownership: onCleanup, getOwner, runWithOwner; cómo Solid libera recursos automáticamente.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 12, 'untrack, batch, on', 'controlar el tracking', 'Leer sin trackear (untrack), agrupar cambios (batch), y dependencias explícitas con on() y defer.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 13, 'createRoot y disposal', 'raíces reactivas', 'createRoot para crear un scope reactivo manual, cuándo hace falta, y el ciclo de vida de disposición.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 14, 'Signals avanzados', 'equals y opciones', 'Igualdad personalizada (equals: false), signals sin comparación, y patrones para señales que siempre notifican.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 15, 'Control flow: Show y Switch', 'condicionales reactivos', 'Renderizado condicional eficiente: Show con fallback y keyed, Switch/Match, y por qué no usar ternarios crudos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 16, 'Control flow: For e Index', 'listas keyed vs por índice', 'For (keyed por referencia) vs Index (por posición): cuándo cada uno, el coste de reconciliación y errores típicos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 17, 'Dynamic, Portal, ErrorBoundary', 'componentes especiales', 'Dynamic para componentes en runtime, Portal para renderizar fuera del árbol, y ErrorBoundary para capturar errores.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 18, 'Lifecycle y refs', 'onMount, ciclo de vida', 'onMount y el ciclo de vida real de Solid, refs al DOM, forward refs, y cuándo el DOM está disponible.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 19, 'createStore', 'reactividad anidada', 'Stores: objetos reactivos de grano fino y anidados, acceso por proxy, y por qué escalan mejor que muchos signals.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 20, 'setStore y produce', 'mutaciones inmutables', 'Actualizar stores: paths, funciones, arrays, y produce()/modifyMutable para un estilo mutable seguro (tipo Immer).', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 21, 'reconcile y unwrap', 'diff de datos externos', 'reconcile() para fusionar datos externos preservando referencias, unwrap() para obtener el objeto crudo, y sus usos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 22, 'Estado global', 'stores compartidos', 'Patrones de estado global sin librerías: un store en un módulo o createRoot, y cómo compartirlo entre componentes.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 23, 'Context', 'createContext, useContext', 'La API de contexto de Solid: proveer y consumir estado por el árbol, con reactividad intacta y sin prop drilling.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 24, 'createMutable', 'el store mutable', 'createMutable para un proxy de escritura directa; su potencia, sus peligros, y cuándo (casi nunca) usarlo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 25, 'Integrar librerías', 'interoperar con JS', 'Envolver librerías no reactivas: from()/observable, integrar con Web APIs, y crear tus propios primitivos reactivos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 26, 'createResource', 'async como primitivo', 'El async first-class de Solid: createResource, estados (loading/error), refetch, y el source reactivo que lo dispara.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 27, 'Suspense', 'coordinar la carga', 'Suspense y SuspenseList: coordinar múltiples resources, fallbacks, y evitar cascadas de spinners.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 28, 'Transitions', 'startTransition, useTransition', 'Transiciones concurrentes: mantener la UI vieja mientras carga la nueva, useTransition y su estado pending.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 29, 'ErrorBoundary a fondo', 'errores en async', 'Manejo de errores con async: cómo se propagan a ErrorBoundary, reset, y patrones de reintento robustos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 30, 'Derivaciones async', 'createAsync y el futuro', 'El nuevo modelo de datos: createAsync (Solid Router / 2.0), señales async, y hacia dónde va la reactividad async.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 31, 'Patrones de data fetching', 'cache, dedup, prefetch', 'Patrones reales: deduplicación, cache, prefetch en navegación, mutaciones optimistas y revalidación.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 32, 'SolidStart', 'el meta-framework', 'SolidStart sobre Vinxi/Nitro: crear el proyecto, la estructura, y qué añade sobre Solid puro.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 33, 'File routing', 'rutas y layouts', 'El enrutado por archivos de Solid Router: rutas anidadas, layouts, rutas dinámicas y route data.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 34, 'Modos de render', 'SSR, streaming, CSR, SSG', 'Los modos de renderizado: SSR síncrono y en streaming, CSR, y prerender/SSG; cuándo cada uno.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 35, 'Server functions', '"use server"', 'Funciones que solo corren en el servidor con "use server": RPC type-safe, serialización, y la frontera cliente/servidor.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 36, 'Actions y forms', 'mutaciones progresivas', 'Actions para mutaciones, formularios con progressive enhancement, useSubmission, y estado optimista.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 37, 'Data loading', 'query, cache, createAsync', 'Cargar datos con query() y cache, preload en el router, createAsync, y revalidación tras una action.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 38, 'Auth y middleware', 'sesiones y protección', 'Sesiones y auth en SolidStart, middleware de peticiones, cookies, y proteger rutas y server functions.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 39, 'El compilador de Solid', 'jsx-dom-expressions', 'Cómo Solid compila JSX a DOM real y a expresiones reactivas: babel-plugin-jsx-dom-expressions, y por qué compilar gana.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 40, 'Rendimiento y Solid 2.0', 'lo que viene', 'Optimización extrema, el nuevo runtime reactivo (async transparente) de Solid 2.0, y benchmarks frente al ecosistema.', NULL, NULL, NULL);
INSERT INTO level VALUES ('solid', 41, 'Síntesis', 'arquitectura y trade-offs', 'El modelo mental completo, arquitectar una app real de principio a fin, comparación con el ecosistema y cuándo Solid NO es la elección.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 0, 'Ontología', 'El mapa de Swift', 'La visión aérea del lenguaje: el modelo de tipos y valores, protocolos y genéricos, concurrencia estructurada, macros, memoria y el ecosistema.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 1, 'Fundamentos', 'tipos, opcionales, closures', 'La base del lenguaje: instalar el toolchain, tipos y variables, opcionales (el corazón de Swift), colecciones, funciones y closures.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 2, 'El modelo de tipos', 'structs, enums, protocolos', 'Structs vs clases, enums con valores asociados, protocolos, genéricos y el manejo de errores con typed throws.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 3, 'Concurrencia', 'async/await y actores', 'La concurrencia moderna: async/await, actores, Sendable, la concurrencia estricta de Swift 6, streams y redes con URLSession.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 4, 'Sintaxis y control', 'la gramática completa', 'El resto de la sintaxis: control de flujo, `guard`, `defer`, bucles con etiquetas, operadores propios y precedencia.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 5, 'Strings y texto', 'Unicode bien hecho', 'El tipo String de Swift: grafemas frente a bytes, índices, `Substring`, expresiones regulares y formateo localizado.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 6, 'Colecciones a fondo', 'protocolos y algoritmos', 'La jerarquía de Collection: Sequence, Collection, RandomAccess; algoritmos, `lazy`, y escribir tu propia colección.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 7, 'Opcionales a fondo', 'el arte de la ausencia', 'Todo sobre los opcionales: encadenamiento, `map`/`flatMap`, `guard let`, los peligros del force unwrap y el diseño de APIs opcionales.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 8, 'Funciones y closures', 'captura y escape', 'Funciones de primera clase: captura de variables, `@escaping`, `@autoclosure`, closures que retienen, y funciones anidadas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 9, 'Valor y referencia', 'la semántica que define Swift', 'La diferencia profunda entre value types y reference types: copia, identidad, mutabilidad, y cómo elegir en cada caso.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 10, 'Enums avanzados', 'modelar con precisión', 'Enums indirectos, genéricos, con raw values; modelar estados imposibles fuera del dominio y el pattern matching completo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 11, 'Protocolos a fondo', 'POP y sus límites', 'Programación orientada a protocolos: extensiones con implementación por defecto, requisitos asociados, y dónde el enfoque se rompe.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 12, 'Genéricos avanzados', 'restricciones y where', 'Genéricos en serio: cláusulas `where`, especialización, tipos condicionalmente conformes y el sistema de resolución.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 13, 'some y any', 'opacos y existenciales', 'Los dos modos de abstracción: tipos opacos (`some`) y existenciales (`any`); su coste en rendimiento y cuándo usar cada uno.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 14, 'Property wrappers', 'comportamiento reutilizable', 'Property wrappers: cómo funcionan, escribir el tuyo, `projectedValue`, y los que ya usas sin saberlo en SwiftUI.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 15, 'Result builders', 'DSLs en el lenguaje', 'Result builders: la magia detrás de SwiftUI; construir tu propio DSL declarativo y entender qué genera el compilador.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 16, 'Macros', 'metaprogramación', 'Las macros de Swift: freestanding y attached, SwiftSyntax, escribir una macro propia y depurar su expansión.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 17, 'Errores avanzados', 'typed throws y diseño', 'El sistema de errores: `typed throws`, `Result`, `rethrows`, diseñar jerarquías de error y la conversión en las fronteras.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 18, 'Memoria y ARC', 'ciclos y captura', 'Automatic Reference Counting: retain/release, ciclos de retención, `weak` y `unowned`, y diagnosticar fugas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 19, 'Copy-on-write', 'el coste de los valores', 'Cómo Swift hace baratos los value types: copy-on-write, `isKnownUniquelyReferenced`, y escribir tus propios tipos COW.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 20, 'Ownership', 'borrowing y consuming', 'El modelo de ownership de Swift: `borrowing`, `consuming`, tipos no copiables (`~Copyable`), y su parentesco con Rust.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 21, 'Unsafe y punteros', 'bajar al metal', 'Las APIs unsafe: punteros tipados y crudos, buffers, gestión manual de memoria, y cuándo se justifica salir del jardín.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 22, 'Interoperabilidad', 'C, C++ y Objective-C', 'Swift con el mundo exterior: importar C y C++, el puente con Objective-C, y exponer Swift a otros lenguajes.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 23, 'Swift 6 y aislamiento', 'data-race safety', 'La concurrencia estricta de Swift 6: aislamiento de actores, `Sendable`, regiones de aislamiento, y migrar código legado.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 24, 'Actores a fondo', 'global actors y reentrada', 'Actores en serio: `@MainActor`, global actors propios, reentrada, prioridad, y los errores de diseño más comunes.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 25, 'AsyncSequence', 'streams asíncronos', 'Secuencias asíncronas: `AsyncStream`, `AsyncThrowingStream`, escribir la tuya, backpressure y cancelación.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 26, 'Concurrencia estructurada', 'tasks y grupos', 'La estructura del paralelismo: `Task`, `TaskGroup`, `async let`, herencia de prioridad, cancelación cooperativa y `withTaskCancellationHandler`.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 27, 'Distributed actors', 'actores en red', 'Actores distribuidos: el modelo, los sistemas de actores, serialización, y su uso en sistemas repartidos entre procesos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 28, 'SPM y módulos', 'organizar el código', 'Swift Package Manager: paquetes, targets, dependencias, control de acceso entre módulos y binarios precompilados.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 29, 'Swift Testing', 'el framework moderno', 'El nuevo framework de testing: `@Test`, `#expect`, parametrización, traits, y la migración desde XCTest.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 30, 'Swift en el servidor', 'Vapor y Hummingbird', 'Swift fuera de Apple: servidores con Vapor o Hummingbird, SwiftNIO por debajo, y desplegar en Linux con Docker.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 31, 'Embedded Swift', 'sin runtime completo', 'Embedded Swift: el subconjunto para microcontroladores y entornos restringidos; qué se pierde y qué se gana.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 32, 'Swift multiplataforma', 'Linux, Windows, Wasm', 'El estado real fuera de Apple: la biblioteca estándar, Foundation en Linux, Windows, y WebAssembly.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 33, 'El compilador', 'SIL y optimización', 'Cómo compila Swift: el pipeline hasta SIL, la especialización de genéricos, el whole-module optimization, y leer el SIL generado.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 34, 'Rendimiento', 'medir y afinar', 'Optimizar Swift: Instruments, el coste de los existenciales y del dispatch dinámico, `@inlinable`, y los benchmarks honestos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 35, 'Diseño de APIs', 'las guidelines', 'Las API Design Guidelines de Swift: nombrar con claridad, argumentos etiquetados, y diseñar bibliotecas que se leen como prosa.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 36, 'Swift Evolution', 'cómo cambia el lenguaje', 'El proceso de evolución: leer una propuesta, entender por qué se aceptó, y seguir hacia dónde va Swift.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 37, 'Errores comunes', 'y cómo salir', 'Los tropiezos clásicos: abuso de opcionales, clases donde tocaba struct, retención accidental y la concurrencia mal entendida.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 38, 'Swift comparado', 'Rust, Kotlin, Go', 'Situar Swift entre sus pares: seguridad de memoria frente a Rust, ergonomía frente a Kotlin, simplicidad frente a Go.', NULL, NULL, NULL);
INSERT INTO level VALUES ('swift', 39, 'Síntesis', 'el lenguaje completo', 'La síntesis: el modelo mental unificado de Swift, decisiones de diseño en código real, y un plan de dominio continuo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 0, 'Ontología', 'El mapa de TCA', 'La visión aérea de The Composable Architecture: State, Action, Reducer, Effect y Store; composición, dependencias y testing exhaustivo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 1, 'TCA: el modelo', 'Point-Free en Swift', 'The Composable Architecture: el Elm/Redux de Swift por Point-Free; flujo unidireccional para SwiftUI.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 2, 'Reducers y efectos', 'State, Action, Effect', 'El reducer de TCA: una función pura de estado y acción que devuelve efectos; Effect para lo asíncrono.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 3, 'Composición y test', 'dependencies, TestStore', 'La C de Composable: componer reducers, la inyección de dependencias, y el testing exhaustivo con TestStore.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 4, 'Swift para TCA', 'value types y macros', 'Las piezas del lenguaje que TCA explota: structs y enums como valores, protocolos, y las macros de Swift 5.9+.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 5, 'La macro @Reducer', 'el boilerplate desaparece', 'Cómo `@Reducer` genera el andamiaje: el enum de acciones, los conformances, y qué escribe realmente por ti.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 6, '@ObservableState', 'observación fina', 'La observación moderna: `@ObservableState` sobre el Observation framework; SwiftUI solo redibuja lo que cambió.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 7, 'Modelar el State', 'el dominio como valor', 'Diseñar el State: structs anidadas, hacer imposibles los estados inválidos, y qué NO debe vivir en el estado.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 8, 'Modelar la Action', 'enums que cuentan qué pasó', 'Diseñar las acciones: eventos de usuario vs respuestas del sistema, acciones anidadas, y BindableAction.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 9, 'El body del reducer', 'operadores y orden', 'El `body`: componer con `Reduce`, el orden de ejecución de los operadores, y `_printChanges` para depurar.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 10, 'Effect a fondo', 'async como valor', 'Los efectos: `.run` con async/await, `.send` desde dentro, `.none`, y por qué el efecto es un valor devuelto y no un side effect.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 11, 'Cancelación', 'debounce y throttle', 'Controlar el tiempo: `.cancellable`, cancelar por id, debounce de búsquedas, y evitar respuestas obsoletas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 12, 'El sistema @Dependency', 'inyección sin ceremonia', 'swift-dependencies: `@Dependency`, el DependencyValues, y por qué sustituir el reloj y la red cambia el testing.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 13, 'DependencyKey', 'live, test y preview', 'Definir tu propia dependencia: `DependencyKey`, los valores liveValue/testValue/previewValue, y `@DependencyClient`.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 14, 'Composición: Scope', 'padre e hijo', 'Conectar un reducer hijo dentro del padre con `Scope`; el key path del estado y el case path de la acción.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 15, 'Colecciones', 'forEach e IdentifiedArray', 'Listas de features: `IdentifiedArray`, el operador `forEach`, y acciones dirigidas a un elemento por id.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 16, 'Opcionales y enums', 'ifLet e ifCaseLet', 'Features opcionales: `ifLet` para estado opcional y `ifCaseLet` para un enum de destinos; el ciclo de vida del hijo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 17, 'Navegación como dato', 'el árbol de estado', 'La idea central: la navegación es estado, no imperativo; modelar a dónde estás como un valor del dominio.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 18, '@Presents', 'sheets, alerts, popovers', 'Presentación basada en estado: `@Presents`, `PresentationAction`, y conectar sheets, alertas y diálogos de confirmación.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 19, 'StackState', 'navegación en pila', 'Pilas de navegación: `StackState` y `StackAction`, empujar y sacar pantallas, y el deep linking como estado inicial.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 20, 'Bindings y SwiftUI', 'formularios', 'Conectar controles de SwiftUI: `@Bindable`, `BindingReducer`, y formularios sin escribir una acción por campo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 21, 'TestStore', 'testing exhaustivo', 'El TestStore: afirmar CADA cambio de estado y CADA efecto; si algo cambia y no lo declaras, el test falla.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 22, 'Testear efectos', 'relojes y tiempo', 'Testear lo asíncrono: relojes controlados (`TestClock`), avanzar el tiempo a mano, y testear debounce y timers.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 23, 'Testing no exhaustivo', 'y de integración', 'Cuando el testing exhaustivo estorba: `exhaustivity = .off`, tests de integración de varias features, y el equilibrio.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 24, '@Shared', 'estado compartido', 'La herramienta `@Shared`: compartir estado entre features sin duplicarlo, con semántica de valor y testeable.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 25, 'Persistencia', '@Shared y almacenamiento', 'Persistir con `@Shared`: appStorage, fileStorage, estrategias propias, y el estado que sobrevive al cierre de la app.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 26, 'Modularizar', 'paquetes SPM', 'Arquitectura a escala: una feature por módulo SPM, tiempos de compilación, previews aislados y fronteras claras.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 27, 'TCA con UIKit', 'más allá de SwiftUI', 'Usar TCA desde UIKit: observar el store, actualizar la vista imperativa, y migrar pantalla a pantalla.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 28, 'Rendimiento', 'observación y coste', 'El coste de TCA: observación granular, evitar recomputar, el tamaño del State, y medir con Instruments.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 29, 'Migrar a TCA', 'una app existente', 'Adoptar TCA sin reescribir: empezar por una pantalla, convivir con MVVM, y la estrategia incremental.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 30, 'TCA vs alternativas', 'el juicio honesto', 'TCA frente a MVVM con @Observable y otras arquitecturas: qué gana, qué cuesta, y cuándo NO usar TCA.', NULL, NULL, NULL);
INSERT INTO level VALUES ('tca', 31, 'Síntesis', 'componer todo', 'La síntesis: arquitectar una app completa con TCA, el ecosistema Point-Free, y llevarse las ideas a cualquier plataforma.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 0, 'Ontología', 'El mapa del 3D en la web', 'La visión aérea: qué es un motor de render, dónde encaja Three.js, WebGL frente a WebGPU, y todo el territorio.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 1, 'Cómo se dibuja un píxel', 'El pipeline gráfico', 'De vértices a fragmentos: las etapas del pipeline, qué hace la GPU en cada una, y por qué existe esta arquitectura.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 2, 'Matemáticas del 3D I', 'Vectores y espacios', 'Vectores, producto escalar y vectorial, normalización, y los cinco espacios de coordenadas que atraviesa un vértice.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 3, 'Matemáticas del 3D II', 'Matrices y transformaciones', 'Matrices de transformación, el orden de multiplicación, la matriz modelo-vista-proyección y por qué importa.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 4, 'Matemáticas del 3D III', 'Rotaciones y cuaterniones', 'Euler y su gimbal lock, cuaterniones como solución, slerp, y cuándo usar cada representación.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 5, 'Primer proyecto', 'Escena, cámara, renderer', 'La tríada mínima, el bucle de render, redimensionar bien, el device pixel ratio y el primer cubo girando.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 6, 'El grafo de escena', 'Object3D y la jerarquía', 'Padres e hijos, matrices locales y globales, el orden de actualización, add y remove, y los grupos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 7, 'Cámaras', 'Perspectiva, ortográfica y el frustum', 'FOV, aspecto, near y far, el z-fighting, la cámara ortográfica y cuándo cada una.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 8, 'Controles', 'Orbit, fly y los propios', 'OrbitControls con damping, los otros controladores, y escribir un control de cámara desde cero.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 9, 'BufferGeometry', 'Atributos y la memoria de la GPU', 'Qué es un atributo, position, normal y uv, los buffers tipados, y el índice que ahorra vértices.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 10, 'Geometrías integradas', 'El catálogo y sus parámetros', 'Box, sphere, plane, torus, extrude, lathe y tube: qué controla cada parámetro y su coste en triángulos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 11, 'Geometría propia', 'Construir vértices a mano', 'Generar una malla desde cero, calcular normales, orientación de caras y el winding order.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 12, 'Modificar geometría', 'Deformar en CPU y en GPU', 'Mover vértices por código, morph targets, y por qué casi siempre deberías hacerlo en el vertex shader.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 13, 'Instancing', 'Miles de objetos en un draw call', 'InstancedMesh, la matriz por instancia, colores por instancia, y el salto de rendimiento que supone.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 14, 'Puntos y líneas', 'Sistemas de partículas y trazos', 'Points y su material, el tamaño atenuado, Line frente a LineSegments, y por qué las líneas gruesas son difíciles.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 15, 'Materiales', 'El catálogo y qué modela cada uno', 'Basic, Lambert, Phong, Standard, Physical y Toon: el modelo de iluminación de cada uno y su coste.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 16, 'PBR I', 'La teoría del renderizado físico', 'La ecuación de renderizado en versión digerible, energía conservada, y qué significan metalness y roughness.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 17, 'PBR II', 'MeshPhysicalMaterial a fondo', 'Clearcoat, transmission, sheen, iridescence, anisotropy: cada capa del material físico y cuándo usarla.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 18, 'Texturas I', 'Cargar, mapear y repetir', 'TextureLoader, wrapping, repeat y offset, filtrado, mipmaps y anisotropía.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 19, 'Texturas II', 'Los mapas de un material', 'map, normalMap, roughnessMap, aoMap, displacementMap y emissiveMap: qué hace cada canal.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 20, 'Texturas III', 'Espacios de color y compresión', 'sRGB frente a lineal, el color management de Three.js, KTX2 con Basis, y el ahorro real de VRAM.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 21, 'Luces', 'El catálogo y su coste', 'Ambient, hemisphere, directional, point, spot y area: qué simula cada una y cuánto cuesta.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 22, 'Sombras', 'Shadow maps y sus artefactos', 'Cómo funciona un shadow map, acne y peter-panning, el bias, el tamaño del mapa y los tipos de filtrado.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 23, 'Entornos e IBL', 'HDRI, envMap y la luz realista', 'Iluminación basada en imagen, cargar un HDRI, PMREM, y por qué un buen entorno mejora más que diez luces.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 24, 'Baking y lightmaps', 'Precalcular la luz', 'Qué se puede precocinar, lightmaps y ambient occlusion horneada, y el flujo desde Blender.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 25, 'glTF', 'El formato estándar del 3D en la web', 'La estructura del formato, glTF frente a GLB, las extensiones, y por qué ganó a OBJ y FBX.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 26, 'Cargar y optimizar assets', 'Draco, Meshopt y gltf-transform', 'Comprimir geometría, el coste de descompresión, y un pipeline real de optimización de modelos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 27, 'Animación de modelos', 'AnimationMixer y clips', 'El sistema de animación, mezclar clips, crossfade, pesos, y controlar la reproducción.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 28, 'Skinning y rigging', 'Personajes con esqueleto', 'SkinnedMesh, los huesos, los pesos de vértice, el coste del skinning y las restricciones prácticas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 29, 'Texto en 3D', 'Geometría, sprites y SDF', 'TextGeometry y su coste, los sprites de texto, troika-three-text con SDF, y el HTML superpuesto.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 30, 'Shaders I', 'GLSL y el modelo mental', 'Qué es un shader, vertex frente a fragment, el paralelismo masivo, y por qué no puedes usar un if como en JS.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 31, 'Shaders II', 'ShaderMaterial, uniforms y varyings', 'Pasar datos desde JS, uniforms y attributes, varyings interpoladas, y el tiempo como uniform.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 32, 'Shaders III', 'El lenguaje GLSL', 'Tipos, swizzling, las funciones integradas, step, smoothstep, mix y clamp como caja de herramientas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 33, 'Shaders IV', 'Ruido y patrones', 'Random determinista, Perlin y simplex, FBM, y construir patrones procedurales que se ven bien.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 34, 'Shaders V', 'Vertex shaders creativos', 'Ondas, desplazamiento por textura, morphing, y recalcular normales tras deformar.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 35, 'Shaders VI', 'Extender los materiales de Three', 'onBeforeCompile, los chunks de shader, y modificar el MeshStandardMaterial sin reescribirlo entero.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 36, 'Raymarching', 'SDF y geometría implícita', 'Distance fields, el bucle de marcha, las operaciones booleanas suaves, y el coste de esta técnica.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 37, 'Post-procesado', 'EffectComposer y los passes', 'El render target, la cadena de passes, bloom, DOF, SSAO, y el orden correcto en el pipeline.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 38, 'TSL I', 'El lenguaje de shading de Three.js', 'Qué es Three.js Shading Language, por qué existe, y cómo un mismo grafo compila a GLSL y a WGSL.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 39, 'TSL II', 'Nodos y composición', 'La API de nodos, las operaciones encadenadas, uniforms y attributes en TSL, y el equivalente de cada función GLSL.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 40, 'TSL III', 'Node materials', 'MeshStandardNodeMaterial, colorNode, positionNode y normalNode: reemplazar partes sin perder el PBR.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 41, 'WebGPURenderer', 'El renderer moderno de Three.js', 'Migrar de WebGLRenderer, qué cambia, el fallback automático a WebGL, y qué features solo existen aquí.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 42, 'Compute en Three.js', 'GPGPU con TSL', 'computeAsync, los storage buffers, partículas simuladas en GPU, y el patrón de doble buffer.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 43, 'Raycasting', 'Detectar el clic en 3D', 'El Raycaster, coordenadas normalizadas, el coste de raycast, y optimizar con bounding volumes y BVH.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 44, 'Física', 'Rapier y el mundo simulado', 'Integrar un motor de física, cuerpos rígidos y colliders, el bucle fijo, y sincronizar con el render.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 45, 'Cámaras y cinemática', 'Movimiento con intención', 'Seguimiento suave, lerp y damping independientes del framerate, shake, y transiciones de cámara.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 46, 'Mundos grandes', 'LOD, culling y streaming', 'Level of detail, frustum culling, occlusion, y cargar el mundo por trozos sin bloquear el hilo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 47, 'Rendimiento I', 'Medir antes de optimizar', 'Draw calls, triángulos, el panel de estadísticas, el spector, y encontrar si el cuello está en CPU o GPU.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 48, 'Rendimiento II', 'Las optimizaciones que valen', 'Merge frente a instancing, compartir materiales, texture atlas, reducir el overdraw y el coste de transparencia.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 49, 'Three.js en frameworks', 'Integración y ciclo de vida', 'El patrón de montaje y limpieza, dispose de verdad, y la integración con Solid, React y Astro.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 50, 'WebXR', 'Realidad virtual y aumentada', 'El modo XR de Three.js, las sesiones, los controladores, hit testing en AR, y el rendimiento en visores.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 51, 'Producción', 'Carga, accesibilidad y fallback', 'La pantalla de carga honesta, detectar capacidad del dispositivo, degradar con dignidad y la accesibilidad del 3D.', NULL, NULL, NULL);
INSERT INTO level VALUES ('three', 52, 'Síntesis', 'Síntesis del 3D en la web', 'La arquitectura de una experiencia 3D completa, el mapa de decisiones técnicas, y hacia dónde va el 3D web.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 0, 'Ontología', 'El mapa de WebGPU', 'Qué es, qué reemplaza, cómo se relaciona con Vulkan, Metal y D3D12, y el mapa completo de la API.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 1, 'Por qué WebGPU', 'Los límites de WebGL', 'El modelo de máquina de estados de WebGL, sus problemas, y qué gana WebGPU: compute, validación previa y multihilo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 2, 'La GPU por dentro', 'SIMD, warps y ocupación', 'Arquitectura de una GPU moderna: unidades de ejecución, la ejecución en grupos, la divergencia y la latencia de memoria.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 3, 'Adaptador y dispositivo', 'Iniciar WebGPU', 'requestAdapter, requestDevice, las features y los límites, el manejo de la pérdida de dispositivo y la detección de soporte.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 4, 'El canvas', 'Contexto, formato y configuración', 'getContext webgpu, configure, el formato preferido, alphaMode y el ciclo de obtener la textura del frame.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 5, 'Buffers', 'Memoria en la GPU', 'createBuffer, los flags de uso, mappedAtCreation, writeBuffer, y el modelo de memoria de la GPU.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 6, 'El primer triángulo', 'Pipeline completo mínimo', 'De cero a un triángulo en pantalla: módulo de shader, pipeline, encoder, render pass y submit.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 7, 'Command encoding', 'El modelo de comandos', 'CommandEncoder, los passes, el command buffer, la cola, y por qué WebGPU graba en vez de ejecutar.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 8, 'Sincronización', 'Asincronía y el mapeo', 'mapAsync, el ciclo de lectura desde GPU, onSubmittedWorkDone, y por qué leer de la GPU es caro.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 9, 'WGSL I', 'El lenguaje de shading', 'La sintaxis inspirada en Rust, la estructura de un módulo, las entry points y las etapas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 10, 'WGSL II', 'Tipos y espacios de dirección', 'Escalares, vectores, matrices, arrays y structs, y los address spaces: function, private, workgroup, uniform, storage.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 11, 'WGSL III', 'Atributos y builtins', 'location, builtin, group y binding, y el catálogo de builtins de cada etapa: position, vertex_index, global_invocation_id.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 12, 'WGSL IV', 'Funciones y control de flujo', 'Declarar funciones, punteros, el control de flujo uniforme, y las restricciones que impone el hardware.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 13, 'WGSL V', 'La librería estándar', 'El catálogo de funciones integradas: matemáticas, empaquetado, derivadas, y las de sincronización.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 14, 'Vertex shaders', 'De atributos a clip space', 'El vertex buffer layout, los formatos de atributo, el step mode para instancing, y la salida a clip space.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 15, 'Fragment shaders', 'Interpolación y salida', 'Las interpolaciones, flat y perspective, múltiples render targets, discard y el coste real del fragment.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 16, 'Overrides y constantes', 'Especialización de pipelines', 'Las override constants, compilar variantes sin duplicar shaders, y el patrón de configuración por pipeline.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 17, 'Bind groups I', 'El modelo de recursos', 'BindGroupLayout, BindGroup, y por qué WebGPU agrupa recursos en vez de bindear uno a uno.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 18, 'Bind groups II', 'Frecuencia de cambio y organización', 'Organizar los grupos por frecuencia, el pipeline layout compartido, y el impacto real en rendimiento.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 19, 'Uniform buffers', 'Datos constantes y alineación', 'Las reglas de alineación de WGSL, el padding que muerde, los dynamic offsets y los tamaños mínimos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 20, 'Storage buffers', 'Lectura y escritura arbitraria', 'Read-only frente a read-write, los arrays de tamaño variable, arrayLength, y el patrón de doble buffer.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 21, 'Texturas I', 'Crear, subir y muestrear', 'createTexture, copyExternalImageToTexture, las vistas, los formatos y el sampler con sus filtros.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 22, 'Texturas II', 'Mipmaps, arrays y cubemaps', 'Generar mipmaps a mano, texture arrays, cubemaps, texturas 3D y los formatos comprimidos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 23, 'Storage textures', 'Escribir desde un shader', 'textureStore, los formatos permitidos, y los casos donde una storage texture supera a un buffer.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 24, 'Render pipeline', 'El estado gráfico completo', 'Primitive, depth-stencil, multisample y blending: cada bloque del descriptor y qué controla.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 25, 'Depth y stencil', 'Profundidad y máscaras', 'El depth buffer, la comparación, el reversed-z, el stencil como máscara y sus operaciones.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 26, 'Blending y transparencia', 'El orden que siempre duele', 'Los factores de mezcla, premultiplied alpha, el orden de dibujado y las técnicas independientes del orden.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 27, 'Render targets', 'Dibujar a textura', 'Off-screen rendering, múltiples attachments, load y store ops, y encadenar passes.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 28, 'Multisampling', 'Antialiasing en hardware', 'MSAA en WebGPU, el resolve target, el coste en memoria, y las alternativas post-proceso.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 29, 'Instancing e indirect', 'Menos llamadas, más objetos', 'draw con instancias, drawIndirect y drawIndexedIndirect, y el patrón de generar comandos desde la GPU.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 30, 'Bundles', 'RenderBundle y el coste de CPU', 'Pregrabar secuencias de comandos, cuándo ayudan de verdad, y sus restricciones.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 31, 'Compute I', 'El modelo de ejecución', 'Workgroups, invocaciones, la jerarquía de IDs, dispatchWorkgroups y elegir el tamaño de workgroup.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 32, 'Compute II', 'Memoria compartida y barreras', 'La var workgroup, workgroupBarrier, storageBarrier, y las condiciones de carrera dentro de un grupo.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 33, 'Compute III', 'Reducciones y prefix sum', 'Los patrones fundamentales del cómputo paralelo: reducción en árbol, scan, y la reducción entre workgroups.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 34, 'Compute IV', 'Ordenación y búsqueda', 'Bitonic sort en GPU, el radix sort paralelo, y por qué ordenar en GPU es un problema distinto.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 35, 'Simulación de partículas', 'El caso canónico', 'Un sistema de partículas íntegramente en GPU: estado en storage, integración, y el render desde el mismo buffer.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 36, 'Estructuras espaciales', 'Grids y vecinos en GPU', 'Hash grid uniforme, contar y ordenar por celda, y la búsqueda de vecinos para colisiones y fluidos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 37, 'GPGPU y ML', 'Matrices, convoluciones y tiling', 'Multiplicación de matrices con tiling en memoria compartida, convoluciones, y el estado de WebNN.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 38, 'Ray tracing por software', 'Trazado en compute shaders', 'Intersecciones, la BVH y su recorrido en GPU, y el path tracing progresivo con acumulación.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 39, 'Deferred y clustered', 'Arquitecturas de render', 'Forward, deferred y forward+, el G-buffer, el clustered lighting y el árbol de decisión entre ellas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 40, 'Renderizado GPU-driven', 'La CPU fuera del camino', 'Culling en compute, generar draw indirect desde GPU, y la arquitectura de los motores modernos.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 41, 'Precisión y estabilidad', 'Floats, NaN y el z-fighting', 'La precisión en GPU, los problemas de escala grande, las coordenadas relativas a cámara y depurar NaN.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 42, 'Rendimiento I', 'Medir en GPU', 'Timestamp queries, occlusion queries, el perfil por pass, y determinar si el cuello está en cómputo o memoria.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 43, 'Rendimiento II', 'Ancho de banda y ocupación', 'El coste de la memoria frente al de la ALU, coalescencia de accesos, y maximizar la ocupación.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 44, 'Depurar WebGPU', 'Errores, scopes y validación', 'Los error scopes, la validación de la API, las etiquetas para mensajes legibles, y las herramientas externas.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 45, 'Portabilidad', 'Límites, features y fallback', 'Los límites garantizados frente a los reales, comprobar features, la degradación a WebGL2 y el estado de soporte en 2026.', NULL, NULL, NULL);
INSERT INTO level VALUES ('webgpu', 46, 'Síntesis', 'Síntesis de WebGPU', 'La arquitectura de un motor propio, el mapa de decisiones, y hacia dónde va la computación gráfica en la web.', NULL, NULL, NULL);
